/**
 * Animated concept explainers: the names a lesson may embed with `::anim[<name>]{…}` (renderer:
 * src/lib/course/detect/directives.ts, player + explainers: src/components/learn/anim/, how to add
 * one: src/components/learn/anim/AUTHORING.md).
 *
 * ONE LINE PER EXPLAINER, alphabetical, so parallel additions merge cleanly. The file name of the
 * explainer (src/components/learn/anim/explainers/<name>.tsx) is the key; the client loads it by
 * that name, so registering here is all the wiring there is.
 *
 *   title    the head of the figure (and its accessible name)
 *   summary  one or two plain sentences: the no-JS / print / loading fallback, so it must stand
 *            alone and state the facts the animation shows
 *   opts     extra attributes the explainer reads: "int", "text" or a list of allowed values.
 *            Every explainer also takes title="…" (override), start="<variant id>" and autoplay="off".
 */
export type AnimOpt = "int" | "text" | readonly string[];
export type AnimMeta = { title: string; summary: string; opts?: Readonly<Record<string, AnimOpt>> };

export const ANIMS: Readonly<Record<string, AnimMeta>> = {
  "audit-hash-chain": { title: "Audit log hash chain: tamper-evident, with a checkpoint", summary: "Each audit event stores the previous event's hash. Editing event #1001 makes its recomputed hash disagree with the stored one, so verification flags it. An attacker who recomputes every later hash makes the chain verify again, which is why the latest hash is also checkpointed to WORM storage: the rewritten head no longer matches it.", opts: { start: ["edit", "rewrite"] } },
  "backpressure": { title: "Backpressure: a producer outruns its consumer", summary: "A producer sends 1,000 messages/s into a queue a consumer drains at 800/s: the 200/s gap piles up until memory runs out. Load shedding, rate-limiting the producer, scaling consumers or spilling to storage each stop the growth, at a different price.", opts: { start: ["none", "shed", "rate", "scale", "spill"] } },
  "cache-invalidation-race": { title: "Write-update vs write-invalidate: the race", summary: "Requests A ($90) and B ($80) update the same product and B commits last, so the database holds $80. With write-update B sets the cache to $80, then A's slower SET leaves a stale $90. With write-invalidate both just delete the key, which is harmless twice, and the next read loads $80.", opts: { start: ["update", "invalidate"] } },
  "cache-patterns": { title: "Cache-aside, write-through, write-behind", summary: "Cache-aside: GET /products/123 misses Redis, the app reads the database (~50 ms) and caches product:123 with a 300 s TTL, so the next read is a ~2 ms hit. Write-through writes the cache and, synchronously, the database before returning. Write-behind returns after the cache write and batches database writes later, losing queued writes if the cache dies first.", opts: { start: ["aside", "through", "behind"] } },
  "cache-tiers": { title: "Multi-tier caching: the request path and invalidation", summary: "A request falls through the browser cache (0 ms), CDN edge (20 ms), API gateway (5 ms), Redis (2 ms) and the database buffer pool (10 ms) before reaching disk (50 ms); the first hit answers. When a price drops from $99 to $79 the write updates the buffer pool, Redis and the gateway are invalidated, the CDN is purged, and browsers keep $99 until max-age expires.", opts: { start: ["read", "inval"] } },
  "cap-partition": { title: "CAP during a partition: refuse or answer stale", summary: "A network partition cuts Node A off from Node B, and a client writes value = 100 to A. A read at B then either gets an error or timeout (CP: consistent, not available, like ZooKeeper or etcd) or B's last known, stale value (AP: available, not consistent, like Cassandra, DynamoDB or DNS).", opts: { start: ["cp", "ap"] } },
  "cap-w01-create-redirect": { title: "TinyLink: a redirect and a create, end to end", summary: "A redirect for /abc1234 is answered by a CDN edge if cached, else from Redis in under a millisecond, else from a PostgreSQL replica, which refills Redis; an unknown code gets a 404. Each redirect publishes a click event to Kafka without waiting for it. Creating a URL checks the rate limit (free tier: 100 requests/minute), takes the next counter value from the server's pre-allocated range (42 → bkBdhgA) with no database lookup, inserts it into PostgreSQL under a uniqueness constraint and caches it in Redis for 86,400 seconds.", opts: { start: ["redirect", "create"] } },
  "cap-w02-flash-claim": { title: "Flash-sale claim: one Lua script, no overselling", summary: "A claim passes the per-minute rate limit (more than 10 attempts gets 429) and the claim:{sale_id}:{user_id} idempotency check, then one atomic Lua script decrements inventory (9,524 → 9,523), stores the claim with a 180 s TTL and records its expiry, and the claimed event goes to claim_events. Two users racing for the last unit run one after the other: A's DECR returns 0 and wins; B's returns -1, is restored to 0 and gets sold out. A retry returns the stored claim without a second decrement, and an unpaid claim's unit returns to the pool when the expiry worker runs, 60 s after the claim's TTL.", opts: { start: ["claim", "last", "retry"] } },
  "cap-w03-order-events": { title: "Event-driven order: outbox to driver, and the failure paths", summary: "The Order Service commits the order row and its outbox row in one transaction and answers the customer; Debezium publishes order.placed to orders.events (keyed by order_id) about 100 ms later. Payment consumes it and publishes payment.confirmed, Restaurant then publishes restaurant.accepted and Driver Matcher driver.assigned, while the audit consumer stores every event in TimescaleDB. Failures: a transient payment timeout goes through orders.retry.1m, 5m and 15m and lands in orders.dlq after 3 retries; a restaurant rejection is permanent and triggers compensation (an alternative restaurant, or a refund); an invalid message is quarantined in orders.dlq.poison at once, with an alert.", opts: { start: ["happy", "fail"] } },
  "cap-w04-invalidation-strategies": { title: "One product change, three invalidation strategies", summary: "Price: price.updated for ABC123 deletes product:ABC123:price and price:ABC123 in Redis first (prices are never cached at the CDN), then cascades to product:ABC123 and product_page:ABC123; if the event is lost, the 30-second safety-net TTL expires the price anyway, and checkout always re-reads it. Inventory: a purchase from 57 to 56 invalidates nothing (57 may show for up to 30 s); only a flip to out of stock deletes the inventory keys and cascades to category:{id}:*. Description: product_metadata is TTL only, so invalidate() skips it and copies live up to 1 hour in Redis and 60 s at the CDN.", opts: { start: ["price", "inventory", "meta"] } },
  "cap-w05-matchmaker-fencing": { title: "Matchmaking queue and a fenced leader", summary: "Players wait in queue:{na}, a Redis sorted set scored by ELO. Every 500 ms the region's leader finds 10 players within ±100 ELO and removes them with a Lua script that accepts its fencing token only if it is at least the highest seen. Leader A (token 42) stalls, its 10 s etcd lease expires and B is elected with a higher token (43), which it uses to remove the next players; when A wakes and tries again with 42, the script rejects it, so no player is double-booked.", opts: { start: ["loop", "failover"] } },
  "cap-w06-order-saga-payment": { title: "Order saga: authorize, compensate, capture", summary: "The saga validates the order, authorizes payment with key order:{id}:auth (a hold, nothing captured), sends the order to the restaurant (seen within 2 s), awaits confirmation and assigns a driver (within 30 s), then captures at pickup, idempotently. If the restaurant rejects after authorization, compensation runs in reverse: there is no driver to release, the authorization is voided with key void:{order_id} (retried until done), the order is cancelled and the customer notified. If capture fails after pickup, nothing is compensated, since pickup can't be undone; the failure is flagged for manual review.", opts: { start: ["happy", "reject", "capture"] } },
  "cap-w07-legal-query-path": { title: "A legal search query, gateway to audit log", summary: "The gateway verifies the JWT and fixes tenant firm_abc123 in an immutable context. The parser turns \"(breach /5 contract) AND damages NOT punitive\" into 9 tokens and an AST (AND of NEAR/5 breach contract, damages, NOT punitive); the builder emits an Elasticsearch bool query (span_near with slop 5, match, must_not) and the service adds the filter is_public OR tenant_id = firm_abc123. Only public_legal_docs and private_docs_firm_abc123 are searched, the search is written to search_audit_log and tenant_id is stripped from the hits. A request that slips tenant_id: firm_def456 into its filters is refused with a SecurityError, and even past that check firm_def456's index is never searched.", opts: { start: ["path", "override"] } },
  "cap-w08-late-event-tiers": { title: "Trending windows, the watermark and late events", summary: "Trending counts unique viewers in a 1-hour window that slides every minute. The watermark trails the newest event time by 5 minutes, so window 10:00–11:00 closes once an 11:05 event is seen; an 11:02 event arriving then still counts, while a 10:52 event arriving after 11:05 is over 5 minutes late and goes to late_events. Events under 5 minutes late update the provisional real-time numbers in ClickHouse; events 45 minutes or 3 hours late wait for the T+1 preliminary job at 6 AM; events 24 hours or more late wait for the T+7 final job, and dashboards say which version each number is.", opts: { start: ["window", "late"] } },
  "cap-w09-tenant-request-path": { title: "A multi-tenant request, layer by layer", summary: "A search from acme.docplatform.com takes its tenant from the verified JWT, and the subdomain must match it. The tenant's config becomes an immutable TenantContext (plan, isolation level, region) and the plan's quota is checked (Standard: 100 search calls a minute). The repository adds tenant_id = acme and SET LOCAL app.current_tenant_id makes PostgreSQL row-level security filter every query; search filters the shared index by tenant_id (Enterprise tenants get their own). A token for another tenant gets 403 Tenant mismatch, the 101st search in a minute is rejected until the window resets, and a query that forgets its tenant filter still returns only acme's rows.", opts: { start: ["request", "blocked"] } },
  "cap-w10-rtb-fanout": { title: "Real-time bidding inside 100 ms", summary: "A bid request spends 0–7 ms at the edge (rate limit, a fraud model under 1 ms, validation and enrichment); then all DSPs are queried in parallel under one 70 ms deadline: open circuits are skipped, bids are collected as they arrive, and a DSP still running at the deadline is cancelled and counted as a breaker failure. A second-price auction with an atomic budget reserve runs at 82–92 ms and the response leaves at about 95 ms, with Kafka logging off the path. A DSP that turns slow opens its breaker after 5 failures and gets half-open trials after 30 s (3 successes close it); under overload, low-value requests get an immediate no bid, the timeout drops to 50 ms and only the top 3 DSPs are queried.", opts: { start: ["normal", "slow", "overload"] } },
  "capacity-littles-law": { title: "Little's Law and the queueing cliff", summary: "L = λ × W: 100 requests/s at 0.2 s keeps 20 requests in flight, exactly 10 pods × 2 workers. At 150/s 30 are needed, so requests queue, W grows and L with it. In a single-server queue, wait ≈ service time × ρ/(1−ρ): 1× at 50% utilization, 4× at 80%, 9× at 90%, unbounded at 100%.", opts: { start: ["little", "util"] } },
  "case-2pc-saga": { title: "2PC vs saga: Book Everything at 12:15 AM", summary: "Two-phase commit asks Flight, Hotel and Car to PREPARE; all three answer PREPARED and keep the seat, room and car locked. When the coordinator crashes at 12:15 AM before COMMIT, 2,000 transactions stay locked: 6,000 items and 4 hours of manual unlocking. A saga commits each booking locally and publishes an event; when the car booking fails, it cancels the hotel and then the flight.", opts: { start: ["2pc", "saga"] } },
  "case-bloom-check": { title: "Bloom filter: setting bits, and a false positive", summary: "A 16-bit filter with h1 = x % 16, h2 = 7x % 16 and h3 = 13x % 16. Inserting evil-phishing-site.com (hash 42) sets bits 10, 6 and 2; checking suspicious-crypto.net (hash 29) finds a 0 among bits 13, 11 and 9, so it is definitely clean. After a second threat (toy hash 22) sets bit 14, a clean URL (toy hash 34) finds bits 2, 14 and 10 all set: a false positive the verify service clears against the database. At GlobalForum's scale, 17.2 billion bits (2.15 GB) and 10 hash functions keep that to 0.1%.", opts: { start: ["basic", "fp"] } },
  "case-bridgelink-tunnel": { title: "BridgeLink: the bore tunnel and self-healing", summary: "adb tcpip 5555 puts device 1d752b81 in TCP mode, adb forward maps the host's port 5000 to it, and bore local 5000 --to bore.pub exposes that port as bore.pub:15750, so adb connect bore.pub:15750 works from anywhere. A health monitor pings each active device every second; on an unplug the tunnel stops and the device goes inactive, and the connection monitor recreates the tunnel when it returns: about 2 seconds down, no developer action.", opts: { start: ["tunnel", "heal"] } },
  "case-cdn-cache-key": { title: "Cache poisoning: a cache key that ignores the user", summary: "ShopFast's CDN cached /api/* for 300 s with cache_key url_path and ignored the origin's headers. User A's GET /api/user/cart missed and was stored under the path alone, so User B, with a different Bearer token, got a HIT on User A's cart (x-cache-hits: 47). The fix makes /api/user/* bypass the cache (ttl 0, private) so the origin answers each token, while public /api/products/* pages stay cached by path.", opts: { start: ["path", "fix"] } },
  "case-digipin-zoom": { title: "GeoHash subdivision: Mumbai down to a 4.8 m cell", summary: "Every GeoHash character is 5 bits and picks 1 of 32 sub-cells, alternating 8 × 4 and 4 × 8 grids. For Mumbai (19.0760°N, 72.8777°E), T is a ~5,000 km cell, TE7 ~156 km, TE7UD2 ~1.2 km × 0.6 km (the delivery-cluster prefix) and TE7UD2EVV ~4.8 m; a check character K makes the 10-character DIGIPIN TE7UD2EVVK.", opts: {} },
  "case-failover-lag": { title: "Leader failover: async loses the last write, sync doesn't", summary: "StreamFlix's US-East leader fails at 2 AM on Black Friday and writes halt for 10 to 30 seconds of detection. With asynchronous replication the most up-to-date follower (Follower 1, writes 1-3) is promoted and write 4, never copied, is lost. With a synchronous US-West standby every confirmed $9.99 payment was already acknowledged by it, so promoting it loses nothing, at the price of slower writes.", opts: { start: ["async", "sync"] } },
  "case-int-overflow": { title: "INT auto-increment hits 2,147,483,647", summary: "At ~4 million events a day, event_log's 32-bit ID passes half its space around day 270 with no alert and reaches 2,147,483,647 after about 18 months. MySQL then hands out the same value again, every INSERT fails with a duplicate-key error the fire-and-forget writer swallows, and reads keep looking healthy. As BIGINT (about 9.2 quintillion values, 8 bytes per row instead of 4) the same 2.15 billion IDs barely register.", opts: { start: ["int", "bigint"] } },
  "case-ios-bridge-pipeline": { title: "iOS Bridge: screenshot loop vs WebRTC engine", summary: "The prototype paid ~100 ms per frame (a simctl screenshot subprocess ~50 ms, PNG ~30 ms, base64 ~20 ms), so 10 FPS at best and only a few FPS, visibly behind, over a WebSocket. The WebRTC engine keeps a one-frame queue that drops the old frame for the newest, FastVideoTrack paces frames at the 45-90 FPS presets, and clicks return over the control WebSocket as scaled taps.", opts: { start: ["ws", "rtc"] } },
  "case-tatkal-bouncer": { title: "Tatkal rush: the bouncer counter and the 5-minute hold", summary: "About 2,000,000 people press Book Now for ~500 seats. A bouncer counter that starts at 500 ticks down once per yes, so only ~500 reach the booking system and the other 1,999,500 get an instant no. Each yes holds one seat for five minutes: paying in time makes it a permanent booking, and an expired hold puts the seat back in the pool for the next person.", opts: { start: ["rush", "hold"] } },
  "case-ws-vs-webrtc": { title: "Video over WebSockets vs WebRTC", summary: "Over WebSockets every one of User A's 30 frames a second goes through ConnectNow's server, which processes and forwards it: 200-500 ms, and CPU at 95% with 50 calls. WebRTC exchanges an SDP offer and answer through a signaling server, uses ICE and STUN to open a direct path, then streams peer to peer over UDP at ~100-300 ms; when NAT blocks that path (~10-20% of connections) a TURN server relays the media.", opts: { start: ["ws", "rtc"] } },
  "circuit-breaker": { title: "Circuit breaker: closed, open, half-open", summary: "Five 3.5 s timeouts in a row trip the breaker OPEN; calls then fail fast in about 10 ms while a 30 s timer runs. HALF-OPEN lets one trial call through: a failure re-opens the breaker, a success closes it.", opts: {} },
  "consistent-hashing": { title: "Consistent hashing: add a node, move one arc", summary: "Keys and partitions hash onto one ring; a key belongs to the next partition clockwise. Adding P4 between P2 and P3 moves only the keys in (P2, P4], from P3 to P4, where hash mod N would move about 80% of keys going from 4 to 5 partitions.", opts: {} },
  "consumer-groups": { title: "Kafka partitions and a consumer-group rebalance", summary: "A topic's partitions keep their messages in order; within a consumer group each partition goes to exactly one consumer. When consumer C joins, a rebalance stops fetching and reassigns partitions (A: 0-1, B: 2-3, C: 4-5); consumers beyond the partition count sit idle.", opts: {} },
  "cron-fencing-token": { title: "Distributed cron: lock timeouts vs fencing tokens", summary: "A 5-minute lock expires while Server 1's slow job is still running, so Server 2 runs the same job and Server 1 later releases Server 2's lock: the job runs twice. With fencing tokens every new leader gets a higher token; once Server B's token 2 is accepted, the old leader's token 1 is rejected and it steps down.", opts: { start: ["lock", "fence"] } },
  "deploy-canary-analysis": { title: "Canary deployment with automated analysis", summary: "v1.1 gets 1%, then 10%, 50% and 100% of traffic, 15 minutes per stage, while its error rate and p99 latency are compared with stable (at most 1 point more errors, 10% more latency). Passing every stage promotes it; a failed analysis sets the canary weight to 0 and deletes the canary pods.", opts: { start: ["promote", "rollback"] } },
  "dlq-poison-pill": { title: "Poison pills and the dead letter queue", summary: "A message whose items field is a string crashes the consumer on every restart, so the offset never moves and 50,000 messages pile up behind it. With a DLQ the consumer catches the ValueError, retries up to 3 times, moves the message to orders.dlq with its error and retry count, and keeps processing; after a fix the message is replayed.", opts: { start: ["none", "dlq"] } },
  "durable-execution-replay": { title: "Durable execution: replay from the event history", summary: "Plain code loses its place when it crashes after reserve_inventory. Temporal records each step as an event (started, reserve_inventory scheduled and completed with res-456, charge_payment scheduled); after a crash a new worker replays the history, completed activities return their stored result instead of running again, and execution continues with charge_payment.", opts: { start: ["plain", "durable"] } },
  "erasure-deletion-orchestrator": { title: "Right to erasure: deleting across every system", summary: "An erasure request starts PENDING with a 30-day deadline. Targets run in priority order, in parallel within a priority: search, files, analytics, third parties, then PostgreSQL, then caches last. A failure (Stripe timing out) stops later groups and leaves the request PARTIALLY_COMPLETED for a retry; verification checks every system before COMPLETED.", opts: { start: ["run", "fail"] } },
  "feed-fanout": { title: "Feed fan-out: push, celebrities and the hybrid", summary: "Fan-out on write pushes each post into every follower's feed cache, so reading a feed is one cache read. A celebrity with 300 million followers would need 300 million writes, about 50 minutes at 100K writes/s. The hybrid pushes for accounts under 10,000 followers and pulls celebrity posts at read time, merging them with the pre-computed feed.", opts: { start: ["push", "celeb", "hybrid"] } },
  "head-of-line-blocking": { title: "Head-of-line blocking: TCP vs QUIC", summary: "Packets 1-5 carry HTTP streams 1, 3 and 5, and packet 2 is lost. Over one TCP connection (HTTP/2) packets 3, 4 and 5 wait for the retransmission of 2, so every stream stalls. QUIC (HTTP/3) orders data per stream, so streams 1 and 5 are delivered at once and only stream 3 waits.", opts: { start: ["tcp", "quic"] } },
  "hot-key-splitting": { title: "Key splitting: one hot key, ten partitions", summary: "Every read of the hot key viral_url_abc hashes to one partition, which saturates. Splitting it into viral_url_abc:0 to :9, one per partition, lets each read pick a random suffix and spreads the load across all ten; a write must update all ten copies, so writes are amplified by the split factor.", opts: {} },
  "idempotency-key": { title: "Idempotency keys: a retry that charges once", summary: "A $99 payment's response is lost and the client times out; without a key its retry charges the card twice. With Idempotency-Key pay_abc123 the server records processing, then completed with txn_789, and the retry gets that cached response. A double click that arrives while the record is still processing is told to wait.", opts: { start: ["nokey", "key", "dbl"] } },
  "incident-response-timeline": { title: "Incident timeline: detect, engage, mitigate, resolve", summary: "v2.3.1 deploys at 14:30 and errors climb from 14:35. The alert fires at 14:42 (time to detect: 7 min), on-call engages at 14:45 (3 min), a rollback started at 14:55 mitigates by 15:00 (18 min from detection), and the service is confirmed restored at 15:15: 40 minutes in all.", opts: {} },
  "ingest-collector": { title: "Event collection: validate, route, dead-letter", summary: "A batch of 500 events is validated event by event: the 497 valid ones go to Kafka in one batch, the 3 invalid ones to events.dead_letter, and the response reports both. A retried batch carries the same client-generated event_ids, so its duplicates are dropped; keying by user_id keeps one user's events in one partition, in order.", opts: { start: ["batch", "retry", "key"] } },
  "io-event-loop": { title: "Thread per connection vs an epoll event loop", summary: "With a thread per connection, each thread blocks in read() and sits idle until its data arrives, which doesn't scale past about 10K connections. An event loop registers every connection with epoll once; one thread blocks in epoll_wait, gets back only the ready connections, handles them in turn and loops.", opts: { start: ["threads", "loop"] } },
  "lab-backpressure": { title: "Break it: backpressure, backlog and lag", summary: "Sliders for producer rate, consumer count and per-consumer throughput, starting at the lesson's 1,000 msg/s into one 800/s consumer. Model: constant rates from an empty queue; the backlog grows by the gap every second and a new message waits backlog ÷ consumer throughput (plus 50 ms of processing). The 200/s gap passes the 100,000-message depth alert after about 8 minutes and the 5-minute lag alert after 20; a second consumer keeps up.", opts: {} },
  "lab-cache-ttl": { title: "Break it: cache TTL vs hit rate", summary: "Sliders for the TTL and traffic in front of a cache-aside database (hit ~2 ms, miss ~55 ms). Model: 3,000 equally popular keys with random arrivals, so each key misses once per TTL and hit rate = λT ÷ (1 + λT). At the lesson's TTL of 300 s and 1,000 req/s that is about 99% hits and 10 req/s to the database; a TTL of 0 sends all 1,000 to the database, and a longer TTL lengthens the worst-case stale window when an invalidation fails.", opts: {} },
  "lab-error-budget": { title: "Break it: error budget and burn rate", summary: "Sliders for the SLO target, incident minutes so far and the current error rate. Model: budget = (1 − SLO) × 30 days, incident minutes count in full, burn rate = error rate ÷ (1 − SLO). 99.9% allows 43.2 minutes: 25 minutes of incidents leave 18.2, 45 leave −1.8 (feature freeze), and 99.99% allows only about 4.3. At 1.44% errors a 99.9% SLO burns 14.4× (page now); 6× pages in business hours, 3× opens a ticket, 1× goes to the weekly review.", opts: {} },
  "lab-feed-fanout": { title: "Break it: feed fan-out, push vs pull", summary: "Sliders for the poster's follower count and the celebrity threshold (10,000 in the lesson). Below the threshold a post is pushed: one cache write per follower at 100,000 writes/s, so 10M followers wait 100 s and 300M about 50 minutes. At or above it the post is stored once and pulled on read: 0 writes, but each feed load adds pulls. The reader is illustrative: 10 of their 500 followed accounts are above 10,000, and about 3× more clear each 10× lower threshold.", opts: {} },
  "lab-hot-partition": { title: "Break it: a hot partition", summary: "Sliders for key skew (the Zipf exponent), shard count and traffic, starting at 1,000 keys, pure Zipf, 10 shards and 10,000 req/s. Model: key k gets traffic in proportion to 1/k^skew, keys land on shards by a fixed hash, and each shard is assumed to handle 2,500 req/s. Key #1 alone takes about 13% of the traffic, so its shard runs at about 1.9× the average; past skew 1 it crosses capacity, and more shards can't help because one key lives on one shard.", opts: {} },
  "lab-queueing-latency": { title: "Break it: utilisation vs queueing delay", summary: "Sliders for utilisation and service time on the lesson's single-server M/M/1 model, wait = service time × ρ ÷ (1 − ρ): about 1× the service time at 50%, 4× at 80%, 9× at 90% and unbounded at 100%. It also shows the wait with 10% more traffic (from 90% busy that is 99%, and 9× becomes 99×) and the queue length ρ² ÷ (1 − ρ). A model, not a measurement: keep critical resources under 70–80%.", opts: {} },
  "lab-replication-lag": { title: "Break it: replication lag vs stale reads", summary: "Sliders for the write rate, replica lag and the number of rows being read (10,000 by default, the lab's assumption), starting at the lesson's 1,000 creates/s and ~50 ms of lag. Model: reads are spread evenly over those rows and a read is stale when its row was written less than one lag ago, so the stale share = writes/s × lag ÷ rows (0.5% here). Reading URLs created in the last 5 s from the primary removes stale reads until the lag passes 5 s.", opts: {} },
  "lab-retry-storm": { title: "Break it: retries and a retry storm", summary: "Sliders for the failure rate, max retries and backoff base, with 100 req/s offered to a dependency. Model: each attempt fails with the chosen probability and retry k fires base × (2^k − 1) s after the original. At 100% failures 3 retries make up to 400 attempts/s (4×); backoff of 1 s, 2 s, 4 s delays the climb but not the total. With the lesson's rate-based breaker (50% failures over at least 100 calls, open for 30 s) the load drops to 0 within about a second.", opts: {} },
  "lab-thundering-herd": { title: "Break it: the thundering herd", summary: "Sliders for how many keys expire together, the traffic on them and TTL jitter, against the lesson's database (1,000 queries/s) and its 100 normal misses/s. Model: expiries spread evenly over ±jitter × 300 s; with no protection every request for a missing key queries the database, with single flight one query per key does. A 5,000 req/s hot key gives 5,100 queries/s (5× overload) and single flight cuts it to about 101; 10,000 keys warmed together spike to 10,100/s even with single flight, and ±10% jitter spreads them over 60 s (about 267/s).", opts: {} },
  "lab-token-bucket": { title: "Break it: token bucket vs a burst", summary: "Sliders for bucket capacity, refill rate and the burst at t3, simulated second by second as in the lesson (refill up to capacity, then serve). With 10 tokens/s and capacity 50, requests of 30, 5, 0 and 60 followed by a steady 10/s: all 30 pass at t0, and at t3 45 of the 60 pass and 15 are rejected. A smaller capacity rejects more of any burst; a refill rate below the steady 10/s rejects requests every second.", opts: {} },
  "late-data-watermark": { title: "Watermarks and allowed lateness", summary: "The watermark is the max event time seen minus a 5-minute out-of-orderness bound, so an older event cannot move it back. A 1-hour window [14:00, 15:00) fires when the watermark passes 15:00, takes a late 14:30 event as an update within 30 minutes of allowed lateness, frees its state after 15:30 and sends later events to a side output.", opts: { start: ["watermark", "late"] } },
  "latency-numbers-zoom": { title: "Latency numbers, zooming out", summary: "On one linear scale, main memory (100 ns) is 200 times an L1 cache reference (0.5 ns), a random 4 KB SSD read (150 μs) is 1,500 times memory, an HDD seek (10 ms) is 67 times an SSD read, a datacenter round trip is 0.5 ms and a packet CA → Netherlands → CA takes 150 ms.", opts: {} },
  "lb-algorithms": { title: "Load balancing: round robin, weighted, least connections", summary: "Round robin sends requests to A, B, C in turn, ignoring load. Weighted round robin with weights 5, 3 and 2 gives A 5, B 3 and C 2 of every 10 requests. Least connections sends each new request to the server with the fewest active connections (B, with 75 against 150 and 120).", opts: { start: ["rr", "weighted", "least"] } },
  "leader-election": { title: "Raft leader election: terms, heartbeats, votes", summary: "The leader's heartbeats reset every follower's randomized election timer. When the leader dies, the first follower to time out becomes a candidate, increments the term and asks for votes; a majority makes it leader. The old leader's stale term is rejected when it returns.", opts: {} },
  "notif-batch-flush": { title: "Batching likes: 10 likes or 300 seconds", summary: "social_like notifications are pushed onto the Redis list batch:{user_id}:social_like instead of being sent one by one. The HYBRID strategy flushes when the 10th like arrives or, failing that, when the flush worker (every 10 s) finds the batch 300 s old; either way one notification such as \"10 people liked your post\" goes out.", opts: { start: ["count", "window"] } },
  "notif-canary-deploy": { title: "Canary deploy: 10% of traffic for 15 minutes", summary: "The new API version first gets 10% of traffic for 15 minutes. If its error rate stays under 1% and p99 latency under 500 ms it rolls out to 100%, then metrics are watched for 30 minutes; if not, rollback_on_failure sends all traffic back to the current version.", opts: { start: ["good", "bad"] } },
  "notif-channel-selection": { title: "Channel selection: type, preferences, quiet hours", summary: "The selector starts from the notification type's channels, then filters by user preferences, quiet hours and device availability. A payment for user-123 goes to Push first with Email as fallback; a marketing email at 23:00 loses Push to quiet hours (only Email and In-App pass); a CRITICAL fraud alert bypasses quiet hours and goes out on Push and SMS at once, with Email as fallback.", opts: { start: ["payment", "marketing", "security"] } },
  "notif-priority-isolation": { title: "Priority isolation: a campaign vs a fraud alert", summary: "A 10M campaign bursts at 100,000+/sec. In one shared topic a CRITICAL fraud alert waits behind millions of campaign messages. With a topic and worker pool per priority, the campaign fills notifications.low (rate-limited to 2K/sec) while notifications.critical, with no rate limit and dedicated workers, delivers the alert straight away.", opts: { start: ["shared", "isolated"] } },
  "notif-status-lifecycle": { title: "Notification status: the valid transitions", summary: "A notification moves PENDING → QUEUED (written to the outbox) → ROUTING (consumed by the router) → SENDING (published to a channel topic) → SENT (provider accepted) → DELIVERED (provider callback) → READ (user interaction). A bounce webhook moves SENT to BOUNCED, which is final; FAILED can only go back to QUEUED, as a retry.", opts: { start: ["delivered", "bounce", "retry"] } },
  "obs-trace-waterfall": { title: "Distributed tracing: spans and context propagation", summary: "Trace abc-123 as a span waterfall: api-gateway 12 ms, then order-service 150 ms, inside which bank-api-call takes 100 ms of the 162 ms total. Service A injects its trace context (traceparent) into the HTTP headers and B extracts it to continue the same trace; without that, B starts a new trace.", opts: { start: ["waterfall", "propagate"] } },
  "olap-rollup-routing": { title: "Rollup tables and query routing", summary: "A 90-day dashboard query scans ~2.7B of fact_sales' ~11B rows, shuffles 50GB and takes 47 seconds. The daily rollup (365K rows a year) answers it from about 90K rows in milliseconds. Each question routes to the coarsest rollup that can answer it: hourly, daily, monthly, or raw facts for single transactions.", opts: { start: ["scan", "routing"] } },
  "outbox": { title: "Transactional outbox: one commit, then the relay", summary: "The order row and its event row commit in one database transaction. A relay reads unpublished outbox rows, publishes them to Kafka and marks them published; if it crashes in between it publishes again, so consumers dedupe by event ID.", opts: {} },
  "ovw-case-2pc-saga": { title: "The whole story: 2PC vs saga at WonderTravel", summary: "WonderTravel's one-click flight, hotel and car booking ran on two-phase commit: PREPARE locks all three, then COMMIT. When the coordinator crashed at 12:15 AM on Black Friday, 2,000 transactions and 6,000 items stayed locked for 4 hours, and a partition left one hotel in doubt. A saga commits each booking locally, compensates backwards when the car fails, uses idempotency keys, and lifted uptime from 99.5% to 99.97%.", opts: {} },
  "ovw-case-bloom": { title: "The whole story: spam detection with a Bloom filter", summary: "A 10x spike takes GlobalForum to 2 billion URL checks a day against 1.2 billion known malicious URLs, which would need 120 GB+ as a database. A Bloom filter of about 17.2 billion bits (2.15 GB) with 10 hash functions answers definitely clean or maybe at a 0.1% false-positive rate, so 99.9% of checks never touch the database. A fast buffer and a 24-hour rebuild keep it current, and the estimated cost falls from $45,000 to $3,200 a month.", opts: {} },
  "ovw-case-bridgelink": { title: "The whole story: BridgeLink, remote Android testing", summary: "An illustrative team's test phones sit on a shelf while its developers work elsewhere. BridgeLink tunnels adb over the internet: adb tcpip 5555, adb forward to a host port, bore local to bore.pub:15750, then adb connect from anywhere, with a caveat that bore traffic is unencrypted. A tunnel manager, WiFi mode and one-second health and connection monitors turn the weekend script into an early open-source CLI (0.3.0, MIT).", opts: {} },
  "ovw-case-cdn": { title: "The whole story: the CDN cache poisoning disaster", summary: "At 10:47 AM on Black Friday about 15,000 ShopFast customers saw strangers' carts while every backend dashboard was green; one curl showed cf-cache-status HIT and x-cache-hits 47. The CDN cached /api/* for 300 seconds keyed by URL path and ignored the origin's private, no-cache headers. The team purged, bypassed personal endpoints, added Vary, classified every endpoint and tested as two users: caching is a security boundary.", opts: {} },
  "ovw-case-crowdstrike": { title: "The whole story: CrowdStrike, one file, 8.5 million blue screens", summary: "At 04:09 UTC on 19 July 2024 CrowdStrike pushed Channel File 291 to Falcon, a kernel driver. Its named-pipe template defined 21 fields but the sensor supplied 20, wildcards hid it, and the first real value in field 21 crashed machines into a boot loop until the file was reverted at 05:27. About 8.5 million devices were hit and many were fixed by hand; the fixes stack input-count and bounds checks, real-value tests and canary rings, because config is code.", opts: {} },
  "ovw-case-digipin": { title: "The whole story: DIGIPIN, a code for every 4 m square", summary: "Giving every 4 m × 4 m square in India a code like TE7UD2EVVK means about 205 billion codes, 500 million+ lookups a day and answers in under 50 ms. GeoHash narrows the cell with each character, from ~5,000 km to ~4.8 m, unlike India Post's real DIGIPIN, a 4 × 4 grid split ten times. The design routes lookups through an edge CDN, Redis and PostGIS, partitions by state across three regions, and benchmarks at 12 ms and 99.95% availability.", opts: {} },
  "ovw-case-facebook-bgp": { title: "The whole story: the day Facebook disappeared", summary: "On 4 October 2021 a maintenance command, which a buggy audit tool failed to stop, took down Facebook's whole backbone. Every DNS site's health check then withdrew its BGP routes at once, so from about 15:50 UTC resolvers got SERVFAIL and retries reached 30 times normal. With remote and out-of-band access down, engineers went to the data centres in person; facebook.com resolved again at 21:20 UTC and traffic returned in stages.", opts: {} },
  "ovw-case-hotstar": { title: "The whole story: Hotstar, 25 million viewers, one match", summary: "During the 10 July 2019 World Cup semi-final Hotstar reached 25.3 million concurrent viewers, arriving at about a million a minute, faster than 5-to-6-minute autoscaling could react. So it pre-warmed and climbed a capacity ladder on concurrency, read the scorecard as a forecast, used the CDN as a shock absorber and switched extras off in panic mode. The run-out that sent millions to the home page was tamed with jitter, backoff and rehearsals that prepared for 50 million.", opts: {} },
  "ovw-case-int-overflow": { title: "The whole story: the integer overflow crisis", summary: "After about 18 months at ~4 million events a day, event_log's 32-bit ID hit 2,147,483,647 and every INSERT failed while reads looked healthy and the writer swallowed the errors. The emergency options are a BIGINT migration (about 9.2 quintillion values), a table split with dual writes, or a reset that loses history. Long term: UUIDs or Snowflake-style IDs, alerts at 50%, 70% and 90% of the ID space, and default to BIGINT.", opts: {} },
  "ovw-case-ios-bridge": { title: "The whole story: iOS Bridge, simulators on any OS", summary: "The iOS Simulator only runs on a Mac, so an illustrative team of eight queues for one MacBook. iOS Bridge builds a scrcpy-style viewer on Meta's idb: the screenshot prototype cost ~100 ms a frame, so the WebRTC engine keeps only the newest frame with 45 to 90 FPS presets, and clicks return as scaled taps. Electron and browser clients, session recovery and a CLI make it an open-source tool (MIT), though builds and signing still need macOS.", opts: {} },
  "ovw-case-irctc": { title: "The whole story: the Tatkal gamble", summary: "At 10:00 a.m. about 2,000,000 people try for roughly 500 Tatkal seats, a 4,000-to-1 contest settled in about ten seconds. A naive seat-count row becomes a hot key, so a waiting room and a bouncer counter give ~500 people a yes and everyone else an instant no, and each yes is a five-minute hold before payment. The 2025 bot defences and the outages when looking and buying shared servers complete the story.", opts: {} },
  "ovw-case-knight-capital": { title: "The whole story: Knight Capital, $440 million in 45 minutes", summary: "On 1 August 2012 Knight's new RLP code reused the flag of Power Peg, a feature retired in 2003 whose fill counter had moved in 2005, and the deploy missed one of eight servers. After 97 ignored emails, flagged orders woke Power Peg at 9:30 and it sent child orders without stopping; rolling back the good servers spread it. About 45 minutes later Knight held $6.65 billion of unwanted positions and a loss of about $440 million.", opts: {} },
  "ovw-case-leap-second": { title: "The whole story: the second that broke the internet", summary: "A leap second adds 23:59:60 to keep UTC within 0.9 seconds of the Earth's spin, and most computers repeat 23:59:59 instead. In 2012 Linux timers ran a second ahead and fired forever, taking down Reddit for 30 to 40 minutes and delaying 400+ Qantas flights; in 2017 Cloudflare measured a negative rtt and some DNS lookups failed. The fixes are monotonic clocks for durations, smearing the second, and the CGPM's 2022 vote to stop adding leap seconds by 2035.", opts: {} },
  "ovw-case-otp": { title: "The whole story: why your OTP arrives late", summary: "An OTP passes an OTP service, an SMS aggregator, the operator's DLT scrubbing and the SMSC before your phone, and can wait behind a promo blast or a 10-hour default validity. In India a template mismatch silently blocks it, as on 8 March 2021 when 25 to 30% of SMS failed. The design fixes are a separate OTP lane, reusing the live code on resend, idempotency keys, fallbacks, measuring delivered rather than sent, and rate limits against SMS pumping.", opts: {} },
  "ovw-case-replication": { title: "The whole story: leader-follower replication and node outages", summary: "StreamFlix runs one leader in US-East for writes and three followers for reads. A follower crash is minor, but when the leader fails at 2 AM on Black Friday writes halt until detection (10 to 30 seconds), election, promotion and redirection, with the old leader fenced to avoid split brain. Synchronous replication loses nothing but slows writes, asynchronous is fast but can lose the last ones, so payments go synchronous and history asynchronous.", opts: {} },
  "ovw-case-ws-webrtc": { title: "The whole story: WebSockets vs WebRTC for video", summary: "ConnectNow's video over WebSockets ran at 240p, 2 to 5 seconds behind, with CPU at 95% on 50 calls, because every frame passed through the server. WebSockets suit text over TCP; WebRTC signals once, then streams peer to peer over UDP in about 100 to 300 ms, with STUN, TURN and SFUs for hard networks and groups. The hybrid cut latency below 100 ms, CPU to 15% at 500 users and bandwidth cost tenfold.", opts: {} },
  "ovw-ip-ad-click-aggregation": { title: "The whole problem: ad click aggregation", summary: "The ad-click-aggregation interview end to end: a billion clicks a day (about 50,000 a second at peak, 200 GB of raw events) counted per ad per minute within a minute, and exactly once for billing. A click tracker logs to Kafka, Flink dedupes and counts by event time into ClickHouse, and an hourly Spark job recomputes final counts from the raw archive. Deep dives build the exactly-once chain (signed click_id, idempotent producer, seen-ID state, checkpoints, overwrite-not-increment) and handle late clicks with watermarks and viral ads with salted two-stage aggregation.", opts: {} },
  "ovw-ip-chat-system": { title: "The whole problem: chat system", summary: "A chat backend delivers one-to-one and group messages to several devices per user with sent, delivered and read ticks. At an assumed 2B messages a day (about 23,000 a second) and 10M open connections, about 200 stateful WebSocket gateways register each device in a Redis session registry, while a stateless chat service assigns each message the next sequence number in its conversation, stores it in Cassandra before acknowledging, routes it to the recipients' gateways, and falls back to push notifications for offline devices. The deep dives cover client message IDs for safe retries, cumulative receipts, sync by last sequence, group fan-out versus pull for huge channels and cheap presence; failures cover gateway crashes, jittered reconnects during deploys and what end-to-end encryption changes.", opts: {} },
  "ovw-ip-distributed-cache": { title: "The whole problem: a distributed cache", summary: "The distributed-cache interview end to end: get, set with TTL and delete at 1M ops/s under 1 ms; about 1 TB of hot data on 20 primaries plus replicas; smart clients hashing keys to 16,384 fixed slots for one hop and cache-aside on a miss. Deep dives show why mod-N resizing remaps ~95% of keys while slots move ~5%, and how a local L1 cache, replica reads and single flight tame a hot key; failover promotes a replica under a new epoch.", opts: {} },
  "ovw-ip-file-sync": { title: "The whole problem: file sync (Dropbox / Google Drive)", summary: "A Dropbox-style sync service keeps a folder identical across devices and shared users, with version history, offline edits and no silently lost edit. At an assumed 50M users that is about 100 PB of files, ~1,160 commits a second, ~9–10 Gbit/s of uploads and ~50 TB of metadata. The client hashes 4 MB chunks, asks which are missing, uploads only those to S3 through pre-signed URLs, then commits a new revision against its base revision; the metadata service appends to the namespace's journal and a notification service wakes other devices, which fetch changes since their cursor and download only new chunks. The deep dives compare fixed and content-defined chunking, limit deduplication to avoid leaks, and turn concurrent edits into a 409 and a conflicted copy; failures cover partial uploads, garbage chunks and huge shared folders.", opts: {} },
  "ovw-ip-hotel-reservation": { title: "The whole problem: a hotel reservation system", summary: "The hotel-reservation interview end to end: guests book a room type for a range of nights, never beyond inventory plus the hotel's overbooking limit, about 30 bookings and 3,000 availability reads a second at peak. Search reads a cached snapshot; the booking decision is one PostgreSQL transaction that inserts a PENDING reservation and reserves every night. Deep dives show the check-then-act race, the conditional update that fixes it, all nights or none, and the hold, pay, confirm saga with expiry, idempotency keys for double clicks and refunds for late payments.", opts: {} },
  "ovw-ip-job-scheduler": { title: "The whole problem: a distributed job scheduler", summary: "The job-scheduler interview end to end: 100 million one-off, delayed and cron jobs, about 5,800 runs a second with 10x spikes at the top of the hour, each started within 5 seconds. Schedulers hold etcd leases on 1,024 partitions and claim due jobs by next_run_at, an outbox feeds Kafka, and workers run each job under a heartbeated lease. Deep dives cover failover with fencing, a timing wheel and look-ahead for the :00 spike, and why runs are at-least-once, made harmless with attempt numbers, a (job_id, scheduled_at) run key and misfire policies.", opts: {} },
  "ovw-ip-key-value-store": { title: "The whole problem: key-value store", summary: "A Dynamo-style key-value store keeps get, put and delete writable through node failures. At an assumed 1B keys of 1 KB (3 TB with 3 replicas) and 200,000 ops a second, replication turns traffic into 500,000 replica operations, about 25 nodes. Keys are hashed onto a ring with virtual nodes and written to the next 3 distinct nodes, succeeding at W = 2 and reading at R = 2 so R + W > N; each node uses a commit log, memtable and SSTables. The deep dives cover virtual nodes, sloppy quorums with hinted handoff, last write wins versus vector clocks, read repair and Merkle trees, then partitions, gossip, tombstones and hot keys.", opts: {} },
  "ovw-ip-leaderboard": { title: "The whole problem: a real-time leaderboard", summary: "The game-leaderboard interview end to end: top 10, my rank and my neighbours within seconds of a match, at about 15,000 score updates a second; 50 million players fit a 5 GB Redis sorted set. Game servers write score events to Kafka (the truth), a writer applies ZINCRBY, and reads use ZREVRANK and ZREVRANGE. Deep dives show why COUNT(*) is O(rank) while a skip list is O(log N), how to break ties and dedupe retries by match_id, merging per-shard top 10s, approximate ranks for the long tail, and rebuilding the derived set.", opts: {} },
  "ovw-ip-message-queue": { title: "The whole problem: a distributed message queue", summary: "The Kafka-style log interview end to end: a log rather than a work queue, so billing, analytics and search each keep their own offset and can replay. A million 500-byte messages a second is 500 MB/s in, about 900 TB for 7 days at three replicas, around 50 brokers. Producers send keyed batches to a partition leader, followers fetch, the leader acks once every in-sync replica has the data, and consumers pull. Deep dives cover append-only segments, page cache and zero-copy reads, acks=all with min.insync.replicas=2, leader election with epochs, and delivery semantics set by when offsets are committed.", opts: {} },
  "ovw-ip-metrics-monitoring": { title: "The whole problem: metrics monitoring and alerting", summary: "The metrics-platform interview end to end: 100,000 hosts and 50 million series give 5 million points a second; compression takes a point from 16 bytes to about 1.5, so a raw week is 4.5 TB, not 48. Agents push through a gateway into Kafka, writers keep a 2-hour head and flush blocks to S3, and queries use a label index and rollups. Deep dives cover delta-of-delta and XOR compression, the cardinality trap, and an alert path of its own: pending then firing, grouping 200 alerts into one page, and a watchdog for the watcher.", opts: {} },
  "ovw-ip-news-feed": { title: "The whole problem: news feed", summary: "A news feed shows each user posts from the people they follow in under 200 ms. At an assumed 100M daily users that is about 11,600 feed loads a second, and pushing 10M daily posts to 200 followers each is 2 billion inserts a day, about 800 GB of feed cache, while one 50M-follower post would take over 8 minutes to push. The post service publishes to Kafka, fan-out workers push post IDs into per-user Redis lists, and the feed service merges in celebrities' posts pulled at read time, hydrates from a separate post cache, filters and ranks. The deep dives place the push-pull threshold, skip inactive users, use cursors instead of offsets and keep ranking to tens of milliseconds; failures cover fan-out lag, a lost cache shard and hot celebrity posts.", opts: {} },
  "ovw-ip-notification-system": { title: "The whole problem: notification system", summary: "One notify API lets every service reach users by push, email or SMS with templates, per-category preferences and quiet hours. Transactional traffic averages an assumed ~116 a second, while a 50M-user campaign runs at ~13,900 a second for an hour and an SMS account limit of 1,000 a second stretches 2.5M SMS to about 42 minutes. The API stores each notification with an outbox and answers 202; Kafka high and bulk topics feed a router that applies preferences and caps, and per-channel workers call APNs, FCM, an email provider and SMS gateways. The deep dives make duplicates harmless with idempotency and per-channel dedupe keys, fail over between providers behind circuit breakers, and keep OTPs in their own lane with reserved provider capacity during campaigns.", opts: {} },
  "ovw-ip-pastebin": { title: "The whole problem: Pastebin", summary: "The Pastebin interview end to end: immutable pastes with optional expiry and unlisted links; about 12 writes and 116 reads a second but 10 GB of content a day, ~18 TB in five years, so metadata goes in PostgreSQL and content in S3, with reads served by the CDN. Deep dives compare counter and random IDs (8 base62 characters, 2.2 × 10^14 of them, retry on the rare collision) and make expiry exact with a check on every read, cache TTLs capped at expiry and a background sweeper.", opts: {} },
  "ovw-ip-payment-system": { title: "The whole problem: a payment system", summary: "The payment-system interview end to end: charge customers through payment providers using tokens, refund, pay sellers and reconcile, about a million payments a day with 120 a second at peak, where correctness beats availability. Each payment is a guarded state machine (marked PROCESSING before the PSP is called), success is committed with its ledger entries and an outbox row, and events reach the order service exactly when committed. Deep dives show why a timeout means unknown, one idempotency key per hop, a double-entry ledger that always sums to zero, and daily reconciliation against settlement files.", opts: {} },
  "ovw-ip-proximity-service": { title: "The whole problem: a proximity service", summary: "The Yelp-style nearby-search interview end to end: radius search with filters at about 15,000 searches a second, with edits visible within minutes; 200 million businesses need only a ~10 GB geo index, so every host keeps a full in-memory copy. Deep dives show why two B-tree indexes fail, how geohash cells turn near into prefix lookups, why the search reads the user's cell plus its 8 neighbours (the cell north of tdr1y is tdr4n), and how caching by cell and a separate change-event write path keep search up.", opts: {} },
  "ovw-ip-rate-limiter": { title: "The whole problem: rate limiter", summary: "A gateway rate limiter decides on every request, at an assumed 150,000 checks a second, whether a client is within limits such as 100 requests a minute, adding under 2 ms and answering 429 with Retry-After when not. Each gateway makes one atomic Lua call to a 4-shard Redis Cluster (about 2 GB of counters) with rules pushed from a rules service. The deep dives show the fixed window's 2x burst at the boundary, the sliding window counter (80 × 0.75 + 30 = 90), the token bucket and the GET-compare-SET race; failure modes cover failing open, a local deny cache for noisy clients and splitting limits across regions.", opts: {} },
  "ovw-ip-typeahead": { title: "The whole problem: typeahead search", summary: "Typeahead returns the ten best completions for a prefix within a keystroke, about 70,000 requests a second at an assumed 100M daily users, leaving the server 10 to 20 ms. About 100M prefixes with their top 10 fit in roughly 10 GB, so every suggest server holds the whole dataset in memory, behind a debounced client and a CDN that caches the ~18,000 short prefixes. Offline, search logs flow through Kafka into daily counts with time decay and last-hour trending counts; a builder ranks, filters the blocklist and publishes S3 snapshots that servers swap in atomically. The deep dives store a top-10 list at every trie node, shard by measured prefix ranges when needed, count distinct users and personalise on the client; failures cover bad snapshots, server loss, CDN staleness and typos.", opts: {} },
  "ovw-ip-unique-id-generator": { title: "The whole problem: unique ID generator", summary: "A distributed ID generator hands out unique, 64-bit, roughly time-ordered IDs at an assumed 1M a second with no network call per ID; a random UUID would cost 8 extra bytes per row per index (80 GB per index at 10 billion rows) and scatter inserts. The Snowflake-style layout spends 1 sign bit, 41 bits of milliseconds since a custom epoch (about 69 years), 10 bits of worker ID (1,024 generators) and 12 bits of sequence (4,096 per millisecond), and the 4,097th request in a millisecond waits for the next one. A library in each instance takes its worker ID from an etcd lease and its time from NTP; duplicates come only from a shared worker ID or a clock stepping backwards, and time-ordered IDs make range partitions hot and must reach JavaScript as strings.", opts: {} },
  "ovw-ip-url-shortener": { title: "The whole problem: URL shortener", summary: "At an assumed 100M new links a month and 100 redirects per link, a shortener handles about 40 creates and 4,000 redirects a second and stores 6 billion links (about 3 TB) over five years, using 0.17% of the 62^7 code space. Shorten servers lease blocks of 10,000 IDs from one counter row, scramble and base-62 encode them, and write with put-if-absent; redirects answer 302 from Redis cache-aside over a sharded URL store and publish clicks to Kafka. Failure modes: Redis down falls through to the store, an allocator outage is covered by leased blocks, and abuse and expiry are checked on create and read.", opts: {} },
  "ovw-ip-web-crawler": { title: "The whole problem: web crawler", summary: "A search crawler fetches an assumed 1B pages a month, about 400 a second, ~100 TB of raw HTML at ~320 Mbit/s, while sending at most one request a second to any host; a Bloom filter keeps 10 billion seen URLs in about 12 GB. The loop runs frontier, fetchers (DNS and robots.txt caches), S3 and parser, content dedupe, URL filter and back to the frontier, with new pages published to Kafka for the indexer. The deep dives cover priority queues plus one queue per host with a heap of due times, politeness under RFC 9309, URL normalisation, the Bloom filter, SimHash near-duplicates and spider traps; failures cover leased URLs, recrawling by change rate with conditional GETs, and robots.txt errors.", opts: {} },
  "ovw-lld-elevator-system": { title: "The whole design: Elevator system", summary: "A 10-floor building with two cars: hall calls carry UP or DOWN, car calls just a floor. The controller's dispatch strategy picks the car with the lowest cost to reach the caller, and each car serves its stops with LOOK, keeping on while stops lie ahead and then turning (8, 9, then 1 is 12 floors, not 19). A scripted morning shows calls landing on cars already heading that way; one lock guards buttons and ticks, displays are told after it, and capacity, maintenance, zoning and fire alarms are new strategies or states.", opts: {} },
  "ovw-lld-lru-cache": { title: "The whole design: LRU cache", summary: "A bounded cache with O(1) get and put and no OrderedDict: a dict finds the node, a doubly linked list with sentinels keeps the order, and the eviction policy sees only keys through four hooks, so LRU, FIFO or LFU can be swapped. On a capacity-3 cache, put A, B, C, get A, then put D evicts B and an update never evicts. Because get reorders the list, reads take the lock too; the demo runs 8 threads and 16,000 lookups and ends with exactly 100 entries.", opts: {} },
  "ovw-lld-movie-ticket-booking": { title: "The whole design: Movie ticket booking", summary: "Seats are held all-or-nothing for 10 minutes behind a SeatLockProvider (a dict in the round, Redis SET NX PX in production), and a booking moves HELD to CONFIRMED, EXPIRED or CANCELLED. Fifty users race for A2 and A3 and one wins; payment pay_101 confirms after the hold is re-checked, a retried callback changes nothing, and a payment 601 seconds late is refunded and frees the seat. Per-seat locks are taken in sorted order to avoid deadlock.", opts: {} },
  "ovw-lld-parking-lot": { title: "The whole design: Parking lot", summary: "A 90-minute machine-coding round: clarify what fits where, which spot to give and how to charge, then model ParkingLot as the only stateful class with two injected strategies (spot assignment and pricing) over plain data. A car enters, the strategy picks the lowest floor and smallest fitting spot under one lock, a ticket is issued, and at exit 2 h 5 min is billed as 3 hours, ₹120. Without the lock two gates can park in one spot; the demo races 40 cars for 6 spots.", opts: {} },
  "ovw-lld-pub-sub-logger": { title: "The whole design: Logging framework", summary: "A logging library with three patterns, each with a job: a Chain of Responsibility (level filter, then redaction of card numbers and UPI IDs) decides whether and how a record continues, a pub-sub bus delivers it to sinks subscribed by level and topic, and a Strategy formats it as plain text or JSON. A search error skips the payments alerts, a broken sink is caught and counted, and an async sink takes 4,000 lines from 8 threads without blocking them.", opts: {} },
  "ovw-lld-rate-limiter": { title: "The whole design: Rate limiter", summary: "The classes inside one process: a RateLimiter interface returning a Decision with retry_after, three algorithms (token bucket, fixed window, sliding log), an injected clock, rules turned into limiters by a factory, and a registry with one limiter per client and endpoint. A free user's burst of 7 gets 5 through, lazy refill returns 2.5 tokens in 0.5 s, the OTP window says retry in 19.5 s, and a fixed window lets 6 through at an edge where the sliding log allows 3.", opts: {} },
  "ovw-lld-splitwise": { title: "The whole design: Bill splitting (Splitwise)", summary: "Expenses split equally, exactly or by percentage in integer paise, so every split adds up and balances sum to zero. On a four-friend Goa trip the ledger shows Aarav owed ₹6,516.66 and Meera owing ₹5,233.33; greedy min cash flow turns 6 pairwise debts into 3 payments, and a UPI deep link settles the biggest in one tap. Balance views, expense RPCs and row-level security, the public building blocks of the author's app Chukta, map onto derived balances, atomic writes and members-only access.", opts: {} },
  "ovw-lld-vending-machine": { title: "The whole design: Vending machine", summary: "The State pattern: Idle, HasMoney, Dispensing and SoldOut each answer insert, select, cancel and item-dropped, while the machine holds the data and one lock. A customer inserts ₹10, ₹5 and ₹10, selects ₹20 chips, and change, stock and money are checked before the sale; coins pushed in while dispensing go to the tray. Change comes from the coins in the box: ₹6 from a ₹5 and three ₹2 coins is 2 + 2 + 2, where greedy gets stuck, and with no way to make change the machine refuses.", opts: {} },
  "ovw-sq-aadhaar": { title: "The whole quest: Aadhaar", summary: "Aadhaar has issued 1.45 billion numbers and answers 90 million+ authentications a day in under 200 ms, while brute-force deduplication would take 3,170 years per day of enrolment. Offline kits encrypt enrolment packets for CIDR, where three ABIS vendors must agree 2 of 3; banks (AUAs) reach CIDR through ASAs and get back only a signed Yes or No. The deep dives cover full-gallery dedup, the 200 ms budget (80 ms for the match), PKI, HSMs, Virtual IDs and face authentication, then village-scale enrolment, fallbacks and defences against replayed or cloned fingerprints.", opts: {} },
  "ovw-sq-blinkit": { title: "The whole quest: Blinkit", summary: "Blinkit runs 2,443 dark stores and ~3.6 million orders a day; a true ten minutes leaves about 6 minutes of riding, ~1.5 km of road, so store density, not rider speed, is the lever. Checkout reserves stock then takes payment, an outbox sends the order to a deadline-ordered picker queue, a rider is planned while picking, and a promise engine publishes honest p90 estimates. The deep dives cover store selection, reservations, the saga, picking and batching, then store modes, a store going dark and rain on match night.", opts: {} },
  "ovw-sq-card-network": { title: "The whole quest: Visa and Mastercard", summary: "Card networks process ~434 billion transactions a year between ~14,500 banks: ~13,800 TPS on average, ~55,000 on Black Friday, built for ~100,000. A purchase goes POS, acquirer, network (BIN routing plus a fraud score in under 1 ms) and issuer, and money only moves at clearing and settlement, T+1 to T+2. The deep dives cover the in-memory 200 ms path, fraud scoring, tiered timeouts and stand-in on issuer rules, six-nines data centres and interchange, then 10x scale, idempotent retries, graceful degradation and catching card-testing bots.", opts: {} },
  "ovw-sq-chatgpt": { title: "The whole quest: ChatGPT serving", summary: "ChatGPT serves 1.2 billion weekly users: ~100,000 messages a second at peak is 50 million output tokens a second, and a 4-GPU replica fits ~225 conversations because KV cache, not weights, fills memory. Messages pass the edge, context assembly and a router to a GPU replica, and tokens stream back through a resumable token log. The deep dives cover memory-bound decode, continuous batching, paged KV and prefix caching, tier lanes and slow cold starts, then a dead replica, the degradation ladder and a 5x launch day.", opts: {} },
  "ovw-sq-figma": { title: "The whole quest: Figma multiplayer", summary: "Figma lets up to 500 people share one file, with 2.2 billion+ changes a day; cursors outnumber edits about 36 to 1, and open files fill ~12 TB of memory. Each edit applies locally at once, one multiplayer server per file sequences and echoes it, and a journal saves batches every half second behind checkpoints. The deep dives cover per-property last-writer-wins, the tree and cycles, the flicker rule, cursor fan-out and crash recovery with fencing, then offline merges, huge files and draining a 500-person review.", opts: {} },
  "ovw-sq-google-search": { title: "The whole quest: Google Search", summary: "Google answers ~14 billion searches a day against ~400 billion documents; this design targets 50 to 500 billion pages, 100,000 QPS and under 500 ms, with 25 trillion postings (~180 TB) that must be sharded. Async pipelines crawl and index, while serving scatters each query to every shard, gathers ~10,000 candidates and ranks them. The deep dives cover the inverted index and document sharding, PageRank, tail latency at 1,000 shards and per-stage budgets, then replicas and caching at 10x, a fresh tier for breaking news, hot queries, spam and crawl traps.", opts: {} },
  "ovw-sq-irctc": { title: "The whole quest: IRCTC Tatkal", summary: "At 10:00 about 2 million people try for one train's ~500 Tatkal seats, ~280,000 requests a second in the first 5 seconds, so this is admission control, not storage. A cached read plane serves search; a waiting room, an atomic counter per pool and a single-writer allocator let only the admitted hold, pay and get a PNR. The deep dives cover the hot row, adaptive admission, the booking saga and the defences against bots and touts, then the 10:00 playbook, late payments, double taps and fifty hot trains at once.", opts: {} },
  "ovw-sq-netflix": { title: "The whole quest: Netflix", summary: "Netflix serves 325 million+ members; ~10 million peak streams at 5 Mbps is 50 Tbps, far too much to send from a few cloud regions. A control plane on AWS authorizes playback and returns a manifest, and Open Connect appliances inside ISPs stream the bytes, filled from IXP and S3 tiers. The deep dives cover the adaptive bitrate ladder, Open Connect economics and placement, and circuit breakers with fallbacks, then midnight launches, a failed appliance or region, and what changes for live events.", opts: {} },
  "ovw-sq-s3": { title: "The whole quest: AWS S3", summary: "S3 stores 500 trillion+ objects at 200 million+ requests a second, designed for 11 nines, which at this scale is a floor (~5,000 objects a year). A PUT is erasure-coded into 10 data and 6 parity shards across three AZs, bracketed, then committed in the index; any 10 of 16 shards rebuild the object at 1.6x storage instead of 3x. The deep dives cover AZ loss and repair, strong read-after-write consistency, index partitioning and storage classes, then 503 backoff, correlated failures, concurrent writes and protecting data from stolen keys.", opts: {} },
  "ovw-sq-spotify": { title: "The whole quest: Spotify", summary: "Spotify serves 777 million monthly users from 100 million+ tracks, starting playback in under 200 ms: 5 billion streams a day, ~175,000 a second at peak, ~5.5 Tbps. The Stream Service authorizes once and returns a signed URL, audio comes from the CDN edge (origin only on a miss) and play events go asynchronously to Pub/Sub. The deep dives cover hybrid recommendations and cold start, device, edge and origin caching, the event pipeline and breakers, then album drops, licensing and tunnels, and exactly-once play counts for royalties.", opts: {} },
  "ovw-sq-twitter": { title: "The whole quest: Twitter/X", summary: "X handles ~500 million posts a day and 300,000 timeline reads a second; pushing every post costs 4.2 million timeline writes a second, and one 100-million-follower post would take ~17 minutes. The hybrid design stores the tweet, pushes its ID to most followers' Redis timelines (LTRIM 800) but only ZADDs celebrity posts, and merges both on read before one MGET. The deep dives cover push vs pull, the two-way social graph, trending and hot keys, then cache sharding, Super Bowl backlogs, returning users and deleting a fanned-out tweet.", opts: {} },
  "ovw-sq-uber": { title: "The whole quest: Uber", summary: "Uber runs ~43 million trips a day and must match a rider in under 3 seconds: 1.5 million online drivers ping every 4 s (375,000 updates a second) against ~1,000 trip requests. Pings land in an in-memory H3 index, Pricing quotes an upfront fare, Matching scores nearby drivers and offers the ride for 15 s, and the trip is created exactly once. The deep dives cover H3 rings, surge with smoothing, weighted scoring and ETAs, then city sharding, silent drivers and GPS drift, a regional failover and idempotent trip completion.", opts: {} },
  "ovw-sq-upi": { title: "The whole quest: India's UPI", summary: "UPI moves about 800 million payments a day between 740+ banks in under 2 seconds: ~9,300 TPS on average, 28,000 to 46,000 at peak. Apps (PSPs) talk to the NPCI switch, which resolves the VPA, debits the payer's bank and credits the payee's while money settles bank to bank through the RBI. The deep dives cover cached VPA resolution, a state machine with DEEMED_SUCCESS and auto-reversal by T+1, per-bank circuit breakers and layered security, then a 5x Diwali, data-centre failover, idempotent retries and the April 2025 status-check outage.", opts: {} },
  "ovw-sq-whatsapp": { title: "The whole quest: WhatsApp", summary: "WhatsApp delivers 100 billion+ messages a day to 50 million connected phones: at 2 million connections a server that is 25 servers instead of 500, and deleting delivered messages shrinks 50 TB a day to ~2.5 TB. Erlang chat servers route encrypted blobs via a user registry with one tick, two ticks and blue ticks, while media goes to a separate store. The deep dives cover ~2 KB Erlang processes, the Signal Protocol, offline queues deleted only on ACK and presence with a 60 s TTL, then celebrity status, sender keys, linked devices and the 32-engineer lesson.", opts: {} },
  "ovw-sq-zerodha": { title: "The whole quest: Zerodha Kite", summary: "Kite took 34.5 million orders in a day and peaks at 9:15:00: ~670 orders a second on average, 7,500 in the first minute, near 15,000 at the busiest second, while ~30 million price packets a second stream out. Orders pass gateway, order service, RMS and exchange gateway exactly once; reads come from a hot cache and prices from feed handlers to ticker servers. The deep dives cover idempotency and UNKNOWN orders, the in-memory RMS, tick coalescing, the open spike and failures, then Budget day with Little's law and the edge cases.", opts: {} },
  "ovw-w00-part1-basics": { title: "The whole lesson: system design fundamentals", summary: "System design runs from requirements through high-level design (components and data flow, like the URL shortener's CDN, load balancer, stateless API servers, cache and database) to low-level design (schemas and API contracts). The interview follows four steps: clarify functional and non-functional requirements, estimate, draw the high-level design, then deep-dive. Architecture, sequence and ER diagrams, and sync vs async communication with REST, GraphQL, gRPC and WebSocket, complete the toolkit.", opts: {} },
  "ovw-w00-part2-building-blocks": { title: "The whole lesson: infrastructure building blocks", summary: "Layer by layer: the edge (a CDN cuts a 200ms trip from Tokyo to about 20ms, DNS resolves names, a load balancer spreads 50,000 requests a second and drops servers that fail health checks), the application layer (stateless servers with sessions in Redis, monolith first), the data layer (PostgreSQL by default, cache-aside at a 5.9ms average, S3 for files) and messaging (an event bus, work queues and pub-sub instead of a synchronous chain).", opts: {} },
  "ovw-w00-part3-estimation": { title: "The whole lesson: back-of-the-envelope estimation", summary: "The numbers to memorize (a day is about 100,000 seconds, memory is about 1,000x faster than SSD), then a Twitter-like service end to end: 200M daily users make 4 billion reads a day, about 47,000 requests a second and about 100,000 at peak; about 7 TB of new storage a day and 12.5 PB over five years; about 15 Gbps of egress that a CDN cuts to about 2.2 Gbps; and about 30 API servers, a primary with 2 read replicas and a 256 GB cache.", opts: {} },
  "ovw-w00-part4-networking": { title: "The whole lesson: networking fundamentals", summary: "\"The client connects to the server\" hides DNS, a TCP handshake, a TLS handshake, the HTTP request and load balancer routing, each adding latency. TCP is reliable and ordered but suffers head-of-line blocking; UDP skips the handshake and lost packets; ephemeral ports can run out. HTTP/1.1, HTTP/2 and HTTP/3 over QUIC each remove the previous bottleneck, and latency comes from propagation, transmission, processing and queuing.", opts: {} },
  "ovw-w00-part5-os": { title: "The whole lesson: operating system concepts", summary: "Processes isolate memory while threads share it, which brings race conditions and deadlocks. Virtual memory maps pages through a page table, page faults and the memory hierarchy set the speed, and cache lines reward sequential access. Event loops on epoll replace thread-per-connection, while the page cache, fsync, write-ahead logs, file descriptor limits and container cgroups decide what survives a crash and what scales.", opts: {} },
  "ovw-w00-part6-theory": { title: "The whole lesson: terminology and theory", summary: "The trade-offs (CAP during a partition, PACELC otherwise, ACID vs BASE), scaling (up vs out, sharding, consistent hashing that moves about 1/N of keys, quorum replication where R + W > N), data and messaging (cache stampedes, queue vs stream, at-least-once delivery with idempotent consumers, sagas with compensations) and reliability (N+1 redundancy, circuit breakers and a 99.9% SLO's 43.2-minute monthly error budget).", opts: {} },
  "ovw-w01-capstone-url-shortener": { title: "The whole capstone: TinyLink URL shortener", summary: "TinyLink creates 100 million 7-character links a day with ten redirects per creation; the redirect must take under 100 ms at p99 with 99.99% uptime. That is about 1,160 creates and 11,600 redirects a second with a viral design target of 120,000, and 182.5 billion URLs (about 300 TB replicated) out of 3.5 trillion possible codes. Redirects go CDN, load balancer, Redirect Service, Redis, then sharded PostgreSQL, creation is a separate API service, and clicks go to Kafka; the deep dives allocate ranges of 10,000 counter values per server, absorb viral links at the CDN (over 95%) and in local caches, Redis replicas and suffixed keys, shard by a hash ring on short_code with a user_id index, rate-limit tiers from 100 to 100,000 requests a minute, and choose consistency per operation, then scale 10x by adding instances, nodes and shards.", opts: {} },
  "ovw-w01-hot-keys": { title: "The whole lesson: hot keys and skew", summary: "Traffic follows Zipf's law (the nth key gets about 1/n of the top key's traffic) and with viral content the top 0.01% of keys get over 90%, pushing a hot key's p99 from 20 ms to 500 ms and slowing its neighbours until failures cascade. Hot keys are found by counting per key in a sliding window, with a fixed-memory count-min sketch, or predicted from external signals, and relieved by caching, dedicated read replicas, key splitting (viral_url_abc:0 to :9, writes to all ten), local in-memory caches with pub/sub invalidation, and request coalescing. The URL shortener, whose partitions 3 and 7 take 3,500 and 4,500 requests a second, serves about 7,200 at the CDN, 1,350 from app memory and 360 from Redis, leaving about 90 for the database and dropping p99 from 500 ms to 20 ms; Instagram pulls celebrity posts on read, and write-heavy counters are buffered or sharded.", opts: {} },
  "ovw-w01-partitioning": { title: "The whole lesson: partitioning", summary: "One PostgreSQL instance handles 1,000 requests per second, but at 10,000 its CPU is pegged and 10 ms queries take 500 ms; partitioning splits the data so each machine owns a subset and writes scale. Hash partitioning spreads keys evenly but sends range queries to every partition, range partitioning sends every December write to one partition, and a directory adds a lookup that becomes a single point of failure. Adding a fifth partition to hash % N moves about 80% of the data, while consistent hashing moves only one arc (with virtual nodes for balance); the URL shortener hashes by short_code, survives a 1M-hits-per-second viral link with a 99.99% cache hit rate (about 100 requests a second reach the partition) and starts with simple modulo hashing.", opts: {} },
  "ovw-w01-preview": { title: "The whole lesson: Week 1, data at scale", summary: "One PostgreSQL is fine until it meets 100 million records, 10,000 requests per second, three continents and 99.99% uptime; then the question becomes access patterns, consistency, growth and failure. The week grows it with partitioning (hash, range, directory), replication (sync or async), consistency models, hot-key handling and consistent hashing, applied to three systems: a URL shortener (100M creates and 1B redirects a day), a rate limiter (10,000 req/s across 50 servers) and a session store (10M concurrent sessions). The pitfalls: jumping to solutions, ignoring failures, and over- or under-engineering.", opts: {} },
  "ovw-w01-rate-limiting": { title: "The whole lesson: rate limiting at scale", summary: "Rate limits defend against botnets, runaway scripts, surprise bills and unfair sharing. A fixed window lets 10 requests at 00:55 and 10 at 01:05 through (20 in 10 seconds), a sliding log is exact but stores every timestamp, a sliding counter estimates 8 × 75% + 3 = 9 with two counters, and a token bucket (10 a second, capacity 50) allows bursts. Across 50 servers uncoordinated counters let 100 requests past a limit of 10, so counts go to a central Redis (+1 to 2 ms, a single point of failure), local counters with sync, or sticky servers; the design (10,000 req/s, 100 per user and 1,000 per key a minute, under 5 ms) returns 429 with Retry-After, and when one of three Redis nodes dies (about 33% of counters, 10 to 30 s of failover) it falls back to conservative local limits instead of failing fully open or closed.", opts: {} },
  "ovw-w01-replication": { title: "The whole lesson: replication trade-offs", summary: "Replicas buy availability (one 99.9% server is down ~8.7 hours a year, two ~31 seconds), read scaling (five replicas serve 50,000 reads a second, but writes do not scale) and nearby reads (under 10 ms in Tokyo instead of ~55 ms each way to Virginia), at the price of waiting for coordination or serving stale data. Leader-follower replication can be synchronous (no loss, slow followers stall writes), asynchronous (fast, lagging, unreplicated writes lost) or semi-synchronous; multi-leader must resolve conflicts, and leaderless quorums see the latest write when W + R > N. Lag makes data go backwards or replies appear before messages, so the consistency level is chosen per use case; in the URL shortener a friend gets a 404 for abc123 from a replica ~50 ms behind, fixed by a synchronous replica, primary reads for new URLs or a write-through cache, with failover after 10 to 30 seconds and regional read replicas for ~10 ms redirects.", opts: {} },
  "ovw-w01-session-store": { title: "The whole lesson: session store design", summary: "A session is server-side user data found by the ID in a cookie; the store must answer in under 5 ms at p99 with 99.99% availability for 10 million sessions of 2 KB (20 GB) at 2 to 3 million requests a second, 80% reads. Sticky sessions lose users when a server dies, a distributed store adds a 1 to 2 ms hop, client-side JWTs cannot be invalidated early, so the lesson designs a hybrid: session:{session_id} keys with a 24-hour TTL in Redis Cluster, 6 shards with a primary and replica each (12 nodes), asynchronous replication with replica promotion after a 15 s timeout, and a local cache. Sessions keep a home region (sess_east_abc123); when US-East goes offline its users log in again unless sessions are copied to a backup region, and the decision is Redis Cluster (about $1,800 a month) over DynamoDB (5 to 10 ms) or PostgreSQL plus a cache.", opts: {} },
  "ovw-w02-capstone-flash-sale": { title: "The whole capstone: MegaMart flash sale", summary: "MegaMart sells 10,000 units at 90% off for 10 minutes every hour to up to 5M users, with 3 minutes to check out and no overselling, double charges or lost orders. The estimate gives a 150,000 requests a second peak, 333 claims and 56 checkouts a second, and 2.4M notifications in 30 seconds. The design puts claims in Redis (rate limit, idempotent claim key, atomic Lua decrement), checkout behind idempotency, a Stripe circuit breaker and a 10-second timeout, precomputed notification batches, and a leader-elected scheduler with fencing tokens; an atomic counter beats queue-based claims, checkout-time decrements and per-item locks, and 10x scale shards inventory by region.", opts: {} },
  "ovw-w02-circuit-breakers": { title: "The whole lesson: circuit breakers", summary: "On Black Friday the bank fails half its calls and every payment waits 3.5 s, retries and fails while threads block; a circuit breaker stops calling a clearly failing service, so errors come back in 10 ms and the bank gets room to recover (timeouts and 5xx count as failures, declines don't). In a 10-minute outage it turns 3,500 seconds of waiting into 17.5 seconds of slow failures plus about 10 seconds of fast ones, with fallbacks where a degraded answer beats none but never for payments. Breakers harm when count thresholds open on load spikes, recovery floods the service, servers disagree on state, or an open circuit hides a bad deploy; in production retry, circuit breaker and bulkhead are layered together.", opts: {} },
  "ovw-w02-distributed-cron": { title: "The whole lesson: distributed cron", summary: "Cron on three servers runs a job three times, and naive fixes fail: a crashed lock holder blocks the job forever, a slow job outlives its lock timeout and runs twice. Perfect distributed cron is impossible, so elect one leader with a lease in etcd or ZooKeeper, guard against split brain with fencing tokens, and run idempotent jobs at-least-once. When the leader dies mid-job, persistent execution records, heartbeats, checkpoints and stale-token rejection keep the job from running twice or never; Celery Beat, Kubernetes CronJobs and Temporal each trade these off, and a reliable job combines every week 2 pattern.", opts: {} },
  "ovw-w02-idempotency": { title: "The whole lesson: idempotency", summary: "When the bank call times out you can't tell whether the request or only the response was lost, and POST /payments retried is a double charge. The fix is an idempotency key: check the store, record processing before calling the bank, pass the key to the bank, store the completed result, and on a timeout ask the bank by key. Choose client, server (payment intent) or deterministic keys, keep records at least 10x the retry window (24 hours by default, tiered Redis, PostgreSQL, archive), and handle the edge cases: a reused key with a different body, TTL expiry mid-request, concurrent retries and partial completion.", opts: {} },
  "ovw-w02-preview": { title: "The whole lesson: Week 2, failure-first design", summary: "Week 2 assumes everything you built will fail, and asks how it fails before how it works, focusing on omission and timing failures. It covers timeout budgets, retries with backoff and jitter, idempotency keys, circuit breakers (closed, open, half-open), at-least-once delivery with idempotent receivers, and leader election, applied to three systems: a payment pipeline (days 1 to 3), webhook delivery at 1M an hour, and a distributed job scheduler. The pitfalls: just retrying, long timeouts, treating an open breaker as an outage, and assuming exactly-once is simple.", opts: {} },
  "ovw-w02-timeouts": { title: "The whole lesson: timeouts", summary: "A call that returns nothing is the killer: you can't tell slow from dead, and with 100 threads a downstream that slows from 100 ms to 10 s drops you from 1,000 to 10 requests a second, so timeouts convert slow into down. Set them from percentiles (P99 × 2 to 3, never the average), split a 5 s SLA into a 4.5 s budget (fraud 600 ms, bank 3,500 ms, notification 300 ms), propagate deadlines, and alert on adaptive timeouts that can hide bugs. One slow dependency cascades through thread pools; bulkheads, load shedding and a circuit breaker turn a 15-minute outage on a slow bank day into 5 minutes of fast errors.", opts: {} },
  "ovw-w02-webhooks": { title: "The whole lesson: webhook delivery", summary: "Webhooks push events to systems you don't control, so deliver at-least-once (a 200 arriving after your 30-second timeout makes duplicates unavoidable) and require idempotent receivers that dedupe on event_id. Events flow from Kafka through a dispatcher that fans out to subscription-partitioned queues and workers, retrying over 9 attempts (about 39 hours) before a dead letter queue, with per-entity ordering, HMAC-SHA256 signatures, a 5-minute replay window and secret rotation. At 1M events an hour (2,500 requests a second at peak, 250 async workers), health checks recover a 2-hour outage's 10,000 events by 4:13 PM instead of about 6 PM, with gradual ramp-up, a DLQ dashboard and alerts.", opts: {} },
  "ovw-w03-audit-log": { title: "The whole lesson: an audit log system", summary: "A financial audit log records who did what to which resource, when and from where: every action, 50,000 events a second at peak, kept 7 years. Each action and its audit event commit together through an outbox, flow through Kafka partitioned by actor_id, are never shed under load, go to a DLQ if they fail, and land in TimescaleDB (90 days), ClickHouse (1 year) and S3 Parquet (7 years). Events are append-only and hash-chained, with the latest hash checkpointed to WORM storage; clock skew is handled by sorting on ingestion time.", opts: {} },
  "ovw-w03-backpressure": { title: "The whole lesson: backpressure and flow control", summary: "A service built for 5,000 events a second received 200,000: the queue absorbed, then memory ran out, consumers crashed and the site went down within 10 minutes. Detect it with consumer lag, queue depth and queue wait time; respond by shedding low-priority load, rate limiting producers, scaling consumers (at most one per partition) or spilling to S3. Most systems keep completeness and stability and accept latency, restore rates gradually after an outage, and rate limit at every boundary.", opts: {} },
  "ovw-w03-capstone-orders": { title: "The whole capstone: an event-driven food delivery order system", summary: "500,000 orders a day across 50 cities, 60% at dinner, with seven services reacting to every order, payment confirmed within 3 seconds and a driver within 2 minutes. The estimate is 100 orders/s, 800 events/s and 5,600 deliveries/s, about 26 TB over 2 years. The design writes each order and its outbox event together, publishes to orders.events (32 partitions by order_id), dedupes on event_id, sheds only low-priority events during the rush, retries at 1, 5 and 15 minutes before orders.dlq, keeps an audit trail for the 2% of disputed orders, and scales 10x by adding partitions and sharding the order database by city.", opts: {} },
  "ovw-w03-dead-letters": { title: "The whole lesson: dead letters and poison pills", summary: "One malformed message crash-looped a consumer for 4 hours, leaving 50,000 messages stuck and $847,000 lost. Transient failures retry with backoff, permanent ones go straight to a DLQ, and poison pills are quarantined at once. A DLQ message carries its full context so an engineer can fix the cause and replay it idempotently; retry counts live in headers, old messages are versioned for replay, and depth alerts at 100 and 1,000.", opts: {} },
  "ovw-w03-outbox": { title: "The whole lesson: the transactional outbox", summary: "Saving to the database and then publishing to Kafka loses the event if the process dies in between (23 of 847 charged payments had no order). The outbox writes the order and its event in one transaction, and a poller or CDC (Debezium, about 10–100 ms) publishes it. The edge cases: a publisher crash re-sends, so consumers dedupe by event_id; a 2-hour Kafka outage just grows the outbox; parallel publishers can reorder events, so partition by aggregate_id; alert above 10,000 unpublished rows or 5 minutes.", opts: {} },
  "ovw-w03-preview": { title: "The whole lesson: Week 3, messaging and async processing", summary: "In 2018 a synchronous order chain collapsed on Black Friday: five services at 200 ms each make 1,000 ms, and five at 99.9% availability make 99.5%. Queuing the work fixes it: the API answers in 50 ms and consumers process at their own pace and retry failures, so nothing is lost. The week then adds queue vs log, the transactional outbox, backpressure, dead letter queues and a 7-year audit log onto that system.", opts: {} },
  "ovw-w03-queue-vs-stream": { title: "The whole lesson: queue vs stream", summary: "A queue is work to be done: each message goes to one consumer and is deleted. A stream is events that happened: retained, read by many consumers that each track an offset, and replayable; consumer groups fan out across groups and balance partitions within one. Most systems pair at-least-once delivery with idempotent consumers, key by user_id for per-user order, watch consumer lag (10,000/s in against 1,000/s out is 32.4 million behind in an hour), and pick a stream for replay or many readers, a queue for jobs.", opts: {} },
  "ovw-w04-caching-patterns": { title: "The whole lesson: caching patterns", summary: "A flash sale sent 10,000 requests a second, 5 queries each, at a database that takes 5,000 queries a second; Redis answers in 0.5–2 ms and takes 100,000+ operations a second. Cache-aside loads on a miss, read-through lets the cache load, write-through writes cache and database synchronously, and write-behind returns early and batches writes, risking loss. Real stores mix them with TTLs by staleness, and handle Redis outages with a circuit breaker, failed invalidations with a TTL, and cold starts by warming the top 10,000 products.", opts: {} },
  "ovw-w04-capstone-catalog": { title: "The whole capstone: a global e-commerce product catalog", summary: "50 million products, 500 million page views a day and flash sales that spike 100x: about 6,000 requests a second normally and 600,000 at peak, so a 1% miss rate would mean 6,000 database queries a second and the hit ratio must stay above 99%, on about 300 GB of Redis. Pages fall through browser, CDN, gateway and Redis, with prices on a separate 30-second, event-invalidated path. The deep dives protect the Deal of the Day from a thundering herd, invalidate each data type differently, tier personalization by activity and set a cache matrix where checkout is never cached; at 10x the database breaks first, and a Redis failure degrades to local caches.", opts: {} },
  "ovw-w04-feed-caching": { title: "The whole lesson: feed caching", summary: "Computing a feed on open from 500 followed accounts takes 5 seconds, caching every feed takes 5 TB, and a celebrity post means 50 million cache writes. Fan-out on write makes reads one cache lookup but amplifies writes; fan-out on read is cheap to write but slow to read. The hybrid pushes regular users' posts, stores celebrity posts to be pulled and merges them at read time, and at scale feeds are ranked, sharded by user, trimmed to 500–1,000 posts and skip inactive users.", opts: {} },
  "ovw-w04-invalidation": { title: "The whole lesson: cache invalidation", summary: "A flash sale changed a price from $99 to $79 while the cache held $99 for an hour, and 147 customers were charged a price they weren't shown. TTLs bound staleness, event-driven invalidation deletes keys in about 100–500 ms, and versioned keys switch atomically. Deleting beats updating, because two concurrent updates can leave the slower, older value in the cache; production combines events with a short safety-net TTL, decomposes products by change rate, invalidates only after commit, and retries failed deletes.", opts: {} },
  "ovw-w04-multi-tier": { title: "The whole lesson: multi-tier caching", summary: "A request falls through the browser (0 ms), CDN (20 ms), gateway (5 ms), Redis (2 ms) and the database buffer pool, and each tier holds different data under its own rules: Cache-Control and hashed filenames in the browser, Vary at the CDN, auth checks and rate limits at the gateway, business data in Redis. A $99 → $79 change is invalidated closest to the database first, Redis then gateway then CDN, while browsers wait out max-age; anonymous content is cached everywhere, authenticated responses are private and never cached at the CDN.", opts: {} },
  "ovw-w04-preview": { title: "The whole lesson: Week 4, caching beyond \"just add Redis\"", summary: "A cache hit is fast, but caching is hard: when to invalidate, what to cache, and how 10,000 simultaneous misses can crash a database. The week walks one request path through cache-aside patterns, invalidation ($99 cached while the database says $79), the thundering herd, push vs pull feeds and the CDN → gateway → Redis → database tiers. It ends with Week 3's flow: a price update goes through the outbox and Kafka to an invalidation consumer that deletes the Redis key and purges the CDN.", opts: {} },
  "ovw-w04-thundering-herd": { title: "The whole lesson: the thundering herd", summary: "When a hot key expires under load, every request misses at once: at 10,000 requests a second, a key with half the traffic expiring means 5,100 queries against a capacity of 1,000. Locking, request coalescing, probabilistic early expiration, background refresh and stale-while-revalidate each turn N queries into one, and production combines them per key type. The edge cases: bound lock waits, shield coalesced fetches and fall back to stale data, and extend the stale TTL when refreshes fail.", opts: {} },
  "ovw-w05-capstone-matchmaking": { title: "The whole capstone: a multiplayer game matchmaking system", summary: "Matching 2 million concurrent players on ELO within ±100, with a median wait under 30 seconds, means about 40,000 queued players and 1,300 queue joins a second (4,000 at peak), in just 2.4 MB of queue state. One matchmaker per region is elected in etcd and fences every queue change so nobody is double-booked, ratings are read and written on the primary, match creation is a saga that re-queues players if no server is free, and party membership is an OR-Set. At 10x the 500 ms matching cycle is the bottleneck, solved by splitting each region into ELO bands.", opts: {} },
  "ovw-w05-conflicts": { title: "The whole lesson: conflict resolution", summary: "A cart edited offline on a phone and a laptop, or two users incrementing 100 to 101, loses data under last-write-wins, which only suits values where the latest is best. Vector clocks detect when two writes are concurrent (A:1 vs C:1) instead of guessing. CRDTs merge automatically because merge is commutative, associative and idempotent: a G-Counter sums per-node counts, an OR-Set lets a concurrent add win, and each data type gets its own strategy.", opts: {} },
  "ovw-w05-consistency-models": { title: "The whole lesson: consistency models", summary: "Consistency answers who sees a write, and when: if A writes X=1 on node 1, a read on node 2 may see 1, the old 0, or an error. The spectrum runs from linearizable (one copy) through sequential, causal (a comment never before its post), read-your-writes and monotonic reads to eventual (DNS can take 48 hours). During a partition CP systems refuse and AP systems answer stale; quorums with W + R > N, and choosing per operation (eventual for browsing, strong for checkout, read-your-writes for order history), let one system mix them.", opts: {} },
  "ovw-w05-leader-election": { title: "The whole lesson: leader election and coordination", summary: "After a partition both nodes can act as leader, and timeouts alone can't prevent it: a 6-second GC pause outlasts a 5-second timeout. Fencing tokens fix it: each election issues a higher token, storage remembers the highest, and the old leader's write with token 1 is rejected after token 2. Raft elects with terms and majorities, FLP says favor safety, ZooKeeper and etcd provide ephemeral nodes and leases, and Kafka's epoch fences a returning broker; use 10–30 second leases renewed at a third.", opts: {} },
  "ovw-w05-orchestration": { title: "The whole lesson: saga orchestration and durable execution", summary: "A hand-built orchestrator loses its place on a crash and can't wait hours, version itself or show where a saga is. Durable execution records every step as an event; after a crash the workflow replays and completed activities return their stored results instead of running again. Temporal splits deterministic workflows from side-effecting activities, adds signals, queries and durable timers, and versions code with patched() so in-flight runs keep the old path; Uber's Cadence runs about 12 billion executions a month.", opts: {} },
  "ovw-w05-preview": { title: "The whole lesson: Week 5, consistency and coordination", summary: "Week 4's cached inventory lets two buyers both see the last item and sell it twice; the fixes are locking, check-and-set at commit, or cancelling one order. The week's other problems are a transfer that debits A but can't credit B, two offline edits where last-write-wins loses one, and two nodes that both think they lead. The five days answer them: consistency models, sagas with compensation, durable orchestration, vector clocks and CRDTs, and leader election with fencing tokens.", opts: {} },
  "ovw-w05-saga": { title: "The whole lesson: the saga pattern", summary: "Across microservices a transfer can debit and charge, then fail at inventory, with nothing to roll back, and two-phase commit blocks with locks held and participants in doubt if the coordinator crashes. A saga runs local transactions (reserve inventory, pay, ship, notify) and, on failure, compensating transactions in reverse; shipping is the pivot, after which it retries forward. Compensations are semantic, idempotent and never fail; choreography suits 2–4 steps, orchestration is the default beyond that, and Airbnb's booking waits up to 24 hours for the host before capturing payment.", opts: {} },
  "ovw-w06-advanced-features": { title: "The whole lesson: advanced notification features", summary: "Day 3 adds the features that change what reaches the user. A/B tests hash user_id and test_id into a bucket (control 50, variant_a 30, variant_b 20), and pick a winner only after 1,000 sends and a 10% better click rate. Timing: 20 likes become one batched push (HYBRID: 10 likes or 300 s), digests go out at 6 PM in the user's timezone, scheduled reminders are stored in UTC and polled only by the leader, and the best send time adds a random minute. A multi-channel saga sends primaries together, waits 60 s before a fallback, and escalates an unopened push to SMS after 5 minutes and a call after 15. In-app notifications land in a 100-item Redis inbox with an unread counter and WebSocket delivery via Redis pub/sub, and preferences are hierarchical with optimistic locking.", opts: {} },
  "ovw-w06-capstone": { title: "The whole capstone: a food delivery order system", summary: "Requirements: 5M orders a day with lunch and dinner peaks, restaurants seeing orders within 2 seconds, drivers assigned within 30 seconds, live locations every 3 to 5 seconds, Stripe authorization at order and capture at pickup, and no lost orders, double charges or double assignments. The estimate gives ~230 orders/sec at a 4x dinner peak, ~7,000 writes and ~60,000 reads a second and about 9 TB a year; the design puts order, restaurant and driver APIs in front of Kafka, five workers (order saga, driver matching, payments, notifications, tracking) and PostgreSQL, Redis and S3. The deep dives are the transactional outbox, idempotency keys, row-locked driver assignment, the order saga, Redis GEO location and layered rate limits; at 10x (2,300/sec) it shards by city, and the build order starts with the order flow and payments.", opts: {} },
  "ovw-w06-core-flow": { title: "The whole lesson: the core notification flow", summary: "Day 2 follows one notification down the happy path. Ingest: an idempotency check, validation that returns 400 for bad requests, the notification and outbox row in one transaction, and an outbox processor polling every 100ms (at-least-once). Route: global and category opt-outs, quiet hours that keep only email and in-app for non-critical traffic, push only with an active device token, and channel topics keyed by user_id. Deliver: locale fallback (es-MX, es, en-US), one DeliveryResult per provider, retries at 2, 4 and 8 s plus jitter before FAILED and the DLQ, and UNREGISTERED tokens marked invalid with a fallback. Track: the status state machine, signed provider webhooks, and duplicate callbacks ignored.", opts: {} },
  "ovw-w06-operations": { title: "The whole lesson: operations, monitoring and the interview", summary: "Day 5 makes the notification platform operable: metrics (counters, gauges such as Kafka lag, latency histograms), dashboards for on-call, product and finance, structured JSON logs with a trace_id, and traces that show the push worker's 150 ms is mostly the FCM call. Alerts page on symptoms (delivery under 95% for 5 minutes) and only warn on causes like an open circuit, with runbooks for low delivery (fail over to SES, clean tokens, cut the send rate) and queue backlog (campaign lag on notifications.low is expected; resetting offsets is a last resort for non-critical topics). Deploys avoid peak hours and campaigns, use a 10% API canary for 15 minutes and 25% rolling workers, and keep migrations backward compatible; the 45-minute interview runs requirements, estimation (5,800/sec, 17K peak, 18 TB), the design API → Kafka → router → workers → providers, and deep dives.", opts: {} },
  "ovw-w06-platform-design": { title: "The whole lesson: designing a notification platform", summary: "Day 1 starts with clarifying questions (FERNS): five notification types over push, email, SMS, in-app and WhatsApp; 50M users, 500M notifications a day and 10M-an-hour campaigns; security under 1 s, transactions under 2 s, marketing within a minute, 99.9% delivery for critical alerts. The estimate gives ~5,800/s on average (design for ~20,000/s), 18 TB of queryable records and ~30 TB active, and SMS at ~$3M a month, so channels go push, then email, then SMS. The architecture: the Send API writes the notification and an outbox row in one transaction, an outbox processor publishes to Kafka priority topics, the router applies preferences, the push worker sends to FCM (SENT), and an InvalidToken marks the token invalid and falls back to email.", opts: {} },
  "ovw-w06-preview": { title: "The whole lesson: Week 6, a notification platform", summary: "Week 6 designs one system end to end: notifications for a fintech super-app (transactions, security alerts, marketing, reminders and social) over push, email, SMS, in-app and WhatsApp, for 50M users, 500M notifications a day, campaign bursts of 10M an hour and a 99.9% delivery SLA for critical notifications. Day 1 clarifies, estimates and designs; Day 2 builds the core flow (ingest, route, queue, provider); Day 3 adds templates, digests, scheduling and preferences; Day 4 covers scale, circuit breakers and fallbacks; Day 5 covers operations and a 45-minute interview. Its production example: a rotated device token makes push fail with UNREGISTERED, so retrying is wasted; the fix marks the token invalid, falls back to email or SMS and registers a new token when the app next opens.", opts: {} },
  "ovw-w06-scale-reliability": { title: "The whole lesson: scale, reliability and edge cases", summary: "A 10M-in-an-hour campaign adds 2,800/sec to the ~5,800/sec average (+48%) but bursts past 100,000/sec at Send, so ingestion is throttled in batches of 1,000 at 1,000/sec (about 2.8 hours, inside the 4-hour max) into the low-priority topic; a celebrity's 1M-follower fan-out runs as an async job at 5,000/sec keyed by recipient, and provider limits (FCM 10,000/sec, APNs 4,000/sec, SendGrid 100 requests/sec, Twilio 100/sec) are respected with backoff on 429. Circuit breakers open after 5 failures and test again after 30 seconds with 3 trial calls; email fails over from SendGrid to SES and SMS from Twilio to SNS, while Kafka lag over 1M or 2M degrades the system to shed low priority or keep only critical. Edge cases (invalid and rotated tokens, hard and soft bounces, DST gaps, races handled by re-checking at delivery and SET NX dedup) and cost (SMS at $0.01 a message, $3M+ a month, 100x email) round it out.", opts: {} },
  "ovw-w07-capstone": { title: "The whole capstone: legal document search", summary: "Lawyers search 50M+ public legal documents and their firms' private uploads with boolean, proximity and citation queries; 100M documents at ~65 KB need 26 TB in Elasticsearch plus 50 TB of PDFs, and 50,000 users at 20 searches an hour make about 280 searches a second. The design puts a JWT gateway in front of search, document and citation services, with uploads flowing S3 → OCR → Kafka → indexer into a per-firm private index in 2 to 3 minutes. The deep dives cover the query parser (lexer, AST, ES bool query), five-layer tenant isolation, the citation network (Brown v. Board: 15,234 citations, 0 overruled) and ingestion triage, then 10x scale with type and date indices, hot/warm/cold tiers, alerts on any cross-tenant attempt, and building tenant isolation first.", opts: {} },
  "ovw-w07-indexing-pipeline": { title: "The whole lesson: the indexing pipeline", summary: "PostgreSQL updates Nike Air Max to $150 while search still says $120, and dual-writing from the app breaks when the Elasticsearch write fails, the process crashes in between or retries reorder the writes. Change data capture fixes it: the app writes only to PostgreSQL, Debezium reads the WAL into Kafka (persisted, ordered per partition, replayable) and the indexing pipeline sends bulk requests of 500 or every 5 s, retrying 3 times before dlq.products, while lag is monitored. A 1M-product import at ~100/s through CDC would take about 3 hours, so a separate rate-limited, resumable bulk indexer handles it; mapping changes go to a new index (products_v2) behind the products alias, switched in one atomic call.", opts: {} },
  "ovw-w07-preview": { title: "The whole lesson: Week 7, designing a search system", summary: "SQL LIKE on 50 million products is a 30+ second full scan with no relevance ranking, no typo tolerance and no synonyms, while a search engine answers from an inverted index in 50 ms, ranked by BM25 plus boosts. The week builds product search for 50M products at 10K queries a second, p99 under 200 ms and 5-minute freshness: fundamentals, a CDC indexing pipeline, query processing and relevance, advanced features (autocomplete, did you mean, facets, synonyms), then operations and scale. The estimate: 500 GB at ~30 GB per shard is ~17, rounded to 20 primaries, 40 copies with one replica, on 6 data nodes plus 3 master and 2 coordinating nodes (11 in all).", opts: {} },
  "ovw-w07-relevance": { title: "The whole lesson: query processing and relevance", summary: "\"running shoes\" matches 50,000 documents, so BM25 scores each one: rare terms weigh more (IDF), repeats saturate (k1 = 1.2) and long documents are normalized (b = 0.75), so the short review scores 8.07 against the 150-word guide's 2.91. What the user typed is scored in query context, while selected facets go in filter context: yes/no, never changing the score, and cached as bitsets (about 50 ms first, 1 ms after). Boosting starts with fields (name 3x, brand 2x), adds a phrase bonus, function_score signals (popularity, recency, featured) and an out-of-stock demotion to 20%; when a strict query returns 2 of a minimum 5 results, progressive relaxation drops filters, then tries fuzzy and any-term matching, and quality is measured by zero-result rate, CTR and MRR.", opts: {} },
  "ovw-w07-search-features": { title: "The whole lesson: advanced search features", summary: "Modern search is an experience, not just matching: every keystroke is an autocomplete query over 50M products answered in under 50 ms, using edge n-grams (nike becomes n, ni, nik, nike) ranked by popularity, and \"Did you mean\" appears only when the phrase suggester's fix has over 2x and over 10 results. Results come with facets built from aggregations (2,847 results, then 1,234 for Running Shoes), filters in cacheable filter context, multi-select facets that exclude their own filter, and synonyms (couch, sofa, settee → sofa) at index or query time. Multi-language search routes \"zapatillas\" to name_es through a Spanish analyzer, and personalization boosts a user's brand affinities (purchases count 3x views) without filtering out others, demoting recently viewed items to 0.8 to avoid a filter bubble.", opts: {} },
  "ovw-w07-search-fundamentals": { title: "The whole lesson: search fundamentals", summary: "A B-tree on products.name only helps exact and prefix matches, so LIKE '%Running%' scans all 50 million rows in 30+ seconds and matches characters, not words ('%red%' finds Bored Games); the inverted index flips it to word → documents, so \"running shoes\" is two lookups and an intersection in under 1 ms. Text analysis runs character filters, a tokenizer and token filters (lowercase, stop words, stemming, synonyms), and the same analyzer must run at index and query time. Documents are denormalized with text fields for full-text search, keyword fields for exact match and facets, and multi-fields like brand.keyword; the index is split into shards queried by scatter-gather, about 20 shards of 20-40 GB for 500 GB, with the primary count fixed at creation.", opts: {} },
  "ovw-w07-search-ops": { title: "The whole lesson: search operations and scale", summary: "At 3 AM on Black Friday the cluster sees 50K queries a second, CPU at 95% and p99 at 2.5 s against a 200 ms target. The fix starts with dedicated roles (3 masters, coordinating and data nodes), a shard plan (50M 10 KB products, a 620 GB index, 32 primaries of about 29 GB plus replicas) and capacity sized by the largest of storage, memory and CPU: 6 data nodes at 10K queries a second, about 22 at 50K. Black Friday means pre-scaling 24 hours ahead (12 data, 6 coordinating, 2 replicas), 22 and 10 at peak, graceful degradation and a gradual scale-down; operations add PagerDuty and Slack alerts, automatic recovery from a node failure and restores from daily S3 snapshots (1 to 4 hours for a full cluster loss).", opts: {} },
  "ovw-w08-capstone": { title: "The whole capstone: video streaming analytics", summary: "The capstone designs analytics for a video service with 150M subscribers and 10M peak concurrent viewers, needing a Trending Now under 60 seconds old, creator analytics, daily A/B results and 2 years of history. The estimate: one event every 10 seconds per viewer is 1M events/s, ~37B a day (plan for 50B, 70% heartbeats), 15TB a day raw or 3TB compressed. Regional collectors batch into Kafka (playback keyed by user_id, 7-day retention); Flink computes trending over 1-hour windows sliding every minute into ClickHouse, while Spark feeds BigQuery for daily ETL, late data and A/B analysis. The hard parts: late mobile events buffered in SQLite (5-minute watermark, then T+1 and T+7 jobs), trending by unique viewers normalized by category, rollups and caches for creator dashboards, and a 10x plan that samples heartbeats so 10x traffic costs about 3 to 4x.", opts: {} },
  "ovw-w08-data-modeling": { title: "The whole lesson: data modeling for analytics", summary: "Daily revenue by category is 365,000 rows and answers in 50 ms, but broken down by country, segment and channel it becomes 3.65 billion rows and 45 seconds, and normalized OLTP tables add a JOIN per hop. A star schema puts measures (quantity, revenue, discount, profit) in a fact table at line-item grain, surrounded by denormalized dimensions (product, date, customer, store) joined by surrogate keys, with NULLs mapped to an Unknown row (key -1). Columnar storage reads only the needed columns (1 of 4: 75% less I/O), date partitions let a one-day query skip 364 others, a rollup turns a 60-second query into 50 ms, and partitioning by customer_id would create 10 million tiny partitions.", opts: {} },
  "ovw-w08-ingestion": { title: "The whole lesson: event ingestion at scale", summary: "Without events you're flying blind, so every meaningful action becomes an immutable event with a unique event_id, a type named domain.entity.action, a UTC timestamp and context, under a schema that only evolves backward-compatibly (optional fields or defaults). A lightweight collector stamps received_time, validates against the schema registry (invalid events go to a dead letter queue), enriches with geolocation and user agent, and writes asynchronously to Kafka topics by category (orders kept 90 days, payments indefinitely), which Flink, Spark and an S3 lake read and can replay. Writing synchronously to a database makes the API as slow as the database; Kafka buffers spikes, the collector sheds page views past 90% queue capacity but never orders or payments, and at-least-once delivery is made safe by event_id dedup.", opts: {} },
  "ovw-w08-late-data": { title: "The whole lesson: late-arriving data", summary: "A weekend flash sale showed $2,430,000 on Sunday night and $2,557,000 on Monday morning: the dashboard was incomplete, because offline mobile purchases, delayed payment confirmations and manual entries arrived late, and windowing by processing time puts a 14:30 subway purchase that arrives at 15:45 in the wrong hour. The fix is event time with watermarks (max event time seen minus a 5-minute bound): a window fires when the watermark passes its end, late events within allowed lateness update it, and later ones go to a side output, never dropped silently, with tolerance set from measured lateness and per source. Corrections patch additive metrics or reprocess non-additive ones, store versions instead of overwrites ($50,000, $52,500, then $53,200 final), finalize at T+1 and T+7, and label every number live or final.", opts: {} },
  "ovw-w08-preview": { title: "The whole lesson: Week 8, an analytics pipeline", summary: "Week 8 builds the pipeline that turns an e-commerce platform's 100M events a day (1,000+ a second) into answers, some needed in real time and some that can wait. Day 1 ingests events into Kafka, Day 2 chooses streaming (Flink), batch (Spark) or both, Day 3 models a star schema, Day 4 handles late data with watermarks and reprocessing, Day 5 builds sub-second dashboard queries, and the capstone covers 10M concurrent viewers on a video platform. Its examples: a mobile event sent 30 minutes late moves a dashboard from 1,000 to 1,050 events, and partitioning, pre-aggregation, columnar storage, materialized views and caching cut a 1B-row query from 60 seconds to 200 ms.", opts: {} },
  "ovw-w08-query-layer": { title: "The whole lesson: the query layer", summary: "A marketing dashboard asks for 90 days of revenue by category, region and day, and the query scans 2.7B of fact_sales' ~11B rows, shuffles 50GB and takes 47 seconds: the pipeline works, the query layer is broken. The fixes: pick the engine by access pattern (a warehouse for 10 daily users, ClickHouse or Druid for 10K real-time users), read less with date partitions (January reads 31 and skips 334), clustering and only the needed columns, and compute once with hourly, daily and monthly rollups (45 seconds becomes 50ms) and result caches whose TTL matches freshness. For many tenants: a tenant_id filter or a schema or database per tenant, per-tenant quotas (10 concurrent queries, 100GB a day, 300-second timeout), and measure first, since the top 10 queries were 70% of time and cost.", opts: {} },
  "ovw-w08-stream-batch": { title: "The whole lesson: streaming vs batch processing", summary: "Events reach Kafka at 1,000 a second, and the business asks for revenue right now (1-2% off is fine), this hour, and yesterday (100% exact). Batch (Spark) processes large chunks: hours of latency but exact and cheaper; streaming (Flink) processes every event: seconds of latency but approximate and always on. Lambda runs both and merges them at query time, with the same logic in two codebases; Kappa streams only and reprocesses by replay (1B events at 100K/s, about 3 hours); petabytes and batch ML favour Lambda. The pitfalls: watermarks (latest event time minus 5 minutes) decide when a window fires, late events need allowed lateness or a side output, state needs a TTL, jobs need checkpoints, batch appends duplicate on retry, and skewed keys need salting.", opts: {} },
  "ovw-w09-capstone": { title: "The whole capstone: a multi-tenant enterprise document platform", summary: "500 tenants across the US, EU and APAC (the largest with 50,000 users and 10 million documents) need search under 500 ms p99 and EU data kept in the EU: 100 million documents of 500 KB are 50 TB, 180 TB raw with metadata and three copies, and 1,000 requests a second at peak are 60% search over a ~3 TB index. A global control plane holds only tenant registry, flags, quotas and routing above three independent regional data planes, uploads go straight to the regional bucket via presigned URLs, and the search service adds tenant and permission filters. The deep dives add five isolation layers, quotas by plan, regional routing, verified deletion and defence in depth; at 5,000 tenants PostgreSQL is sharded by tenant_id, and any cross-tenant access pages immediately.", opts: {} },
  "ovw-w09-data-residency": { title: "The whole lesson: data residency and GDPR", summary: "Deutsche Bank wants its employees' personal data kept in the EU, but the whole stack runs in us-east-1 with backups in us-west-2. Of the four patterns (a single region, fully isolated regional deployments, regional data under a global control plane that holds only metadata, and a region per tenant), the last two keep an EU tenant's data in eu-central-1 even when a request lands in the US. Personal data, pseudonymized data, backups and caches stay in the region while aggregated analytics, metrics and config can be global; every processing needs a lawful basis such as contract or consent, consent withdrawals are appended to a log, and transfers out of the EU need an adequacy decision, SCCs or BCRs plus a DPA with every processor.", opts: {} },
  "ovw-w09-noisy-neighbour": { title: "The whole lesson: noisy neighbour prevention", summary: "One tenant's export (847 seconds, 2.3 billion rows) pushes latency from 200 ms to 15,000 ms and takes 95% of the shared capacity, starving everyone else. Defence comes in layers: a per-tenant token bucket at the gateway (429 with Retry-After), concurrency limits and a query guard in the application, per-tenant connection pools and statement timeouts in the database, and CPU, memory and I/O quotas in the infrastructure. Quotas are tiered by plan (60, 1,000 or 10,000 calls a minute), background jobs are scheduled fairly per tenant, and the classic mistakes are a global limiter, silent throttling and one limit for every operation.", opts: {} },
  "ovw-w09-preview": { title: "The whole lesson: Week 9, multi-tenancy, security and compliance", summary: "An enterprise security questionnaire asks about isolation, data location, SOC 2, GDPR deletion, encryption and noisy neighbours: a system built for scale is not yet built for trust, and security must protect against the worst case. The week covers the tenant isolation spectrum from shared tables to a VPC per tenant, throttling a tenant at 800% of its quota, keeping EU data in the EU, deleting one user's data from every system, and five layers of defence in depth. The capstone combines them in an HR platform for 500 enterprise customers and 2 million users with six requirements, from an isolation tier to deletion within 30 days.", opts: {} },
  "ovw-w09-right-to-deletion": { title: "The whole lesson: right to deletion", summary: "A GDPR Article 17 request must be answered within a month, but the user's data sits in a dozen systems, from PostgreSQL and Elasticsearch to Stripe, backups and logs, and only hard deletion or true anonymization counts. A data inventory records each element's locations and deletion method, each system type gets a strategy (immediate, 24 to 48 hours, or expiry), and foreign keys force leaf records first and the user last. The deletion service records the request as PENDING with a 30-day deadline, runs targets in priority order, verifies every system and writes an anonymized audit record; backups expire and are re-applied on restore, orders are anonymized and kept for tax law, shared messages show @deactivateduser and audit logs are anonymized, never deleted.", opts: {} },
  "ovw-w09-security-architecture": { title: "The whole lesson: security architecture", summary: "A pull request commits a live API key and the production database password, and within hours the secret is in git history, Docker layers, CI logs, laptops and forks. Defence in depth stops different attacks at each layer: floods at the perimeter, direct database connections at the private network, cross-tenant requests in the application, stolen backups by encryption, with monitoring logging every attempt. Secrets are fetched at runtime and rotated without restarts, every hop uses TLS or mTLS, keys form a master → tenant → data hierarchy in an HSM, and identity combines bcrypt, MFA, 15-minute access tokens, role-based permissions, a tenant check first and a deny-by-default posture.", opts: {} },
  "ovw-w09-tenant-isolation": { title: "The whole lesson: tenant isolation", summary: "Multi-tenancy replaces a $500-a-month stack per customer with shared servers and a shared database at about $50 each, so isolation depends on the implementation: shared tables with tenant_id (millions of tenants), schema per tenant (thousands), or database per tenant (hundreds, per-tenant backups), with a hybrid of shared tables plus RLS and dedicated databases for enterprise as the default. The tenant comes from the verified JWT and reaches every layer: the repository's tenant filter, PostgreSQL RLS, tenant-prefixed cache keys, logs and background jobs. The classic leaks are a missing WHERE clause, a trusted X-Tenant-ID header and an unprefixed cache key.", opts: {} },
  "ovw-w10-capacity": { title: "The whole lesson: capacity planning", summary: "At 11:47 PM on a Friday a 5x viral campaign exhausts the database and pushes p99 latency to 15 seconds, while a planned system was pre-scaled a day earlier: capacity planning is a cycle of measure, forecast, identify, plan and validate. Headroom is spare capacity over maximum (a 3,000 QPS database at 2,000 has 33%; keep 30%), and load tests show latency within the SLO up to 1,000 RPS and breaking at 1,800. Growing 10% a month, 25% headroom in January becomes 17% in February, so scaling starts then; Little's Law sizes 500 RPS at 0.2 s as 100 in flight, about 36 pods with headroom, and queueing wait grows from 1x at 50% utilization to 9x at 90%. Smoke, load, stress, spike and soak tests, vertical or horizontal scaling and auto-scaling that takes 3 to 5 minutes complete the toolkit.", opts: {} },
  "ovw-w10-capstone": { title: "The whole capstone: a global real-time bidding platform", summary: "10 billion ad requests a day must each be answered in 100 ms p99 (receive the bid request, query the DSPs, run an auction, return the winner) at 99.99% availability, 500,000 requests a second at peak and never more than 0.1% over an advertiser's budget: about 116,000 requests a second on average, 80 TB of audit data a day, ~200 PB over 7 years and 150 servers. The 100 ms splits into 2 + 5 + 75 + 10 + 3 ms with a hard 70 ms DSP timeout, behind GeoDNS, an edge rate limiter and fraud filter, and an auction that reserves budget. 1,000 simultaneous $20 bids against $10 of budget would overspend to $29,990, so budget is a hierarchy of regional allocations and $100 pod leases; the audit trail uses a transactional outbox into Kafka, fraud detection is tiered, the Super Bowl is pre-scaled to 3x, and budget accuracy is the biggest risk.", opts: {} },
  "ovw-w10-deployment": { title: "The whole lesson: deployment strategies", summary: "To improve a system you must change it, so deploy frequently but safely. Big bang means downtime and every user on the new version at once; rolling replaces instances gradually but runs two versions together with a slow rollback; blue-green switches all traffic to an idle environment and back instantly, for twice the infrastructure; canary moves from 1% to 10%, 50% and 100%, compared with the stable version at each stage. Feature flags decouple deployment from release and must be removed once at 100%, a column rename runs as expand, migrate and contract so old and new code both keep working, and rollback is instant for a flag, fast for code and config, and slow and risky for data.", opts: {} },
  "ovw-w10-incidents": { title: "The whole lesson: incident management", summary: "At 3:17 AM the payment service's error rate hits 45%, and preparation, not luck, decides whether the response is calm and structured or panicked: 5% errors against a 1% SLO is an incident, and severity from SEV1 (over $10K an hour, all hands) to SEV4 sets the response. An incident runs detect, triage, respond, mitigate, resolve and learn (SEV1 targets: detect within 5 minutes, engage within 15, mitigate within an hour), with an incident commander who coordinates, a technical lead, a communications lead, mitigation before root cause, updates every 15 minutes and a status page within 10. Blameless postmortems use five whys (down to missing N+1 detection) and owned action items within 48 hours, and on-call stays sustainable with at least 8 people and fewer than 5 pages a shift.", opts: {} },
  "ovw-w10-observability": { title: "The whole lesson: observability", summary: "At 3:47 AM availability drops to 98.2%; with observability the dashboard, logs, traces, metrics and a 3:40 config change point to the root cause in five minutes, because monitoring says when something is wrong and observability helps explain why. Metrics are cheap aggregates (counters, gauges, histograms; RED and USE; low-cardinality labels), logs are structured JSON carrying a trace ID, and traces break a request into spans, such as a 100 ms bank call in a 162 ms request; correlating them turns hours into minutes. The stack collects, stores and shows all three in Grafana, dashboards come in executive, service and debug layers, alerts fire on symptoms with a runbook, and debugging runs from dashboard to traces, spans, logs and recent changes.", opts: {} },
  "ovw-w10-preview": { title: "The whole lesson: Week 10, production readiness", summary: "After nine weeks of designing systems, week 10 is about operating them: a senior engineer can operate, debug and tell when a system is healthy, and has a plan for when it breaks. Day by day: a metric becomes an SLI, an SLO, an SLA and a 43.2-minute monthly error budget; metrics, logs and traces share one trace ID; a canary goes from 1% to 100% with automatic rollback; a headroom table shows Elasticsearch breaking first at twice the traffic; and incidents run from detection through mitigation to a postmortem within 48 hours. The capstone is a real-time bidding platform: 10 billion requests a day, 500,000 a second at peak, 100 ms p99 and 99.99% availability.", opts: {} },
  "ovw-w10-slos": { title: "The whole lesson: SLIs, SLOs and SLAs", summary: "\"Pretty reliable\" can't settle whether an outage lasted ten minutes or an hour, so reliability needs precise words: an SLI is what you measure, an SLO the internal target (99.9%) and an SLA the external promise (99.5%, or credits). Good SLIs come from the golden signals and count good events over valid events at the load balancer, SLOs leave headroom above current performance, and each extra nine costs far more. A 99.9% SLO leaves a 43.2-minute monthly error budget with written policy bands, alerts fire on burn rate (14.4x pages now), dependencies cap you at 99.83%, and the same SLO is translated for engineers, product, executives and customers.", opts: {} },
  "quorum-read-write": { title: "Quorum reads and writes: W + R > N", summary: "With N = 3 replicas, W = 2 and R = 2 overlap: a write acknowledged by A and B and a read answered by B and C share B, so the highest version (v2) wins and read repair fixes C. With W = 1 and R = 1 (1 + 1 < 3) a read can hit a replica that still has v1 after v2 was acknowledged.", opts: { start: ["strong", "eventual"] } },
  "replication-lag": { title: "Replication lag and read-your-writes", summary: "A write lands on the leader and reaches the follower a moment later. A read routed to the lagging follower returns the old value; routing the user's reads to the leader for recently written data (read-your-writes) shows the new value at once.", opts: {} },
  "residency-region-routing": { title: "Data residency: routing by tenant region", summary: "An EU tenant's upload that lands on a US app server is still written to eu-central-1: the router looks up the tenant's region (cache, then the tenants table), and only metadata stays global. If a migration forgets to delete the tenant_region cache key, traffic keeps going to the old region for up to the 1-hour TTL.", opts: { start: ["route", "stale"] } },
  "saga": { title: "Saga: local steps, compensations, the pivot", summary: "An order saga runs Reserve inventory, Create payment, Ship (the pivot) and Send confirmation as local transactions. A failure before the pivot runs the compensations in reverse (refund, then release inventory); after the pivot the saga only moves forward, retrying until it completes.", opts: {} },
  "scd-type2-history": { title: "Slowly changing dimensions: Type 1 vs Type 2", summary: "John moves from Standard to Premium in June. Type 1 overwrites the row, so his Q1 sales count as Premium. Type 2 closes row 1 (valid_to 2024-05-31), adds row 2 (Premium from 2024-06-01), and each sale keeps the surrogate key that was valid when it happened, so revenue by segment is point-in-time.", opts: { start: ["type1", "type2"] } },
  "search-alias-reindex": { title: "Zero-downtime reindex with an alias switch", summary: "The app searches the products alias, which points at products_v1. products_v2 is created with the new mapping, CDC writes to both indexes (products_write points at v2), the old documents are bulk-copied with op_type create, and once counts match within 0.1% one atomic call moves the alias to v2. Searches never stop; v1 is deleted afterwards.", opts: {} },
  "search-bm25-scoring": { title: "BM25: IDF, TF saturation, length normalization", summary: "For \"running shoes\" over 1M documents averaging 50 words: IDF is 2.9957 for running (5% of docs) and 2.3026 for shoes (10%). Doc 1 (45 words, running ×3, shoes ×2) gets saturated TFs of 1.6058 and 1.4148 and scores 8.0683; Doc 2 (150 words, once each) is length-normalized to TF 0.55 and scores 2.9141.", opts: {} },
  "search-edge-ngram": { title: "Edge n-grams: every prefix is an exact term", summary: "Standard tokenization stores \"nike\" as one token, so the prefix \"ni\" matches nothing exactly. Edge n-grams store n, ni, nik and nike (and every prefix of nikon) at index time; at search time the analyzer only lowercases, so \"ni\" is one exact lookup returning nike and nikon, nike first on a sports site.", opts: { start: ["index", "query"] } },
  "search-graceful-degradation": { title: "Graceful degradation under load", summary: "Normal: 60 s cache TTL, 100 results, all features on. p99 over 500 ms (or CPU over 70%, queue over 500) is WARNING: TTL 300 s, 50 results, spell check and personalization off. Over 1,000 ms (or 85%, 1,000) is CRITICAL: TTL 600 s, 20 results, facets and highlighting off, a simple query. Back under the thresholds restores normal.", opts: {} },
  "search-inverted-index": { title: "Inverted index: build once, query by lookup", summary: "Five products are tokenized into term → document lists: running → p1, p2, p4, p5; shoes → p1, p2, p3. The query \"running shoes\" is two lookups and one intersection, p1 and p2, in under a millisecond, where SQL LIKE makes 50 million string comparisons.", opts: { start: ["build", "query"] } },
  "security-zero-trust": { title: "Perimeter security vs zero trust", summary: "In the perimeter model the firewall is the only check: an attacker with phished VPN credentials gets in and reaches the database and API freely. In zero trust every service authenticates and authorizes each request, so the attacker is denied while the app's own mTLS-verified, least-privilege call to the database is allowed.", opts: { start: ["perimeter", "zero"] } },
  "session-sticky-vs-store": { title: "Sticky sessions vs a shared session store", summary: "With sticky sessions, user B always lands on Server 2, which keeps sessions B, E and H in memory; when Server 2 dies those sessions die too and user B is logged out. With a shared Redis Cluster store any server finds session B, so B stays logged in, at the price of a network hop (+1-2 ms) and a new dependency.", opts: { start: ["sticky", "store"] } },
  "slo-error-budget-burn": { title: "Error budget and burn rate", summary: "A 99.9% SLO over 30 days allows 43.2 minutes of bad time. A 10-minute outage on day 5, 15 degraded minutes on day 12 and a 20-minute outage on day 20 leave −1.8 minutes: feature freeze. A 14.4x burn rate spends 2% of the budget in an hour (all of it in about 50 hours) and pages; 6x spends 5% in 6 hours.", opts: { start: ["month", "burn"] } },
  "sq-aadhaar-auth-budget": { title: "Aadhaar authentication: spending the 200 ms", summary: "A bank (the AUA) sends the encrypted PID block via an ASA to CIDR (25 ms). CIDR's HSM decrypts it and checks the signature (15 ms), the record and template load (20 ms) and the 1:1 match takes the largest slice (80 ms); signing, the trip back and overhead (15 + 25 + 20 ms) complete the 200 ms. Only y or n returns, never biometric or personal data, and after an n the bank falls back to another finger, iris, OTP or face.", opts: { start: ["y", "n"] } },
  "sq-blinkit-stock-reservation": { title: "Stock reservations: hold, commit or expire", summary: "Store 412 has 3 packets and two checkouts want 2 each. The guarded UPDATE (reserve only if on_hand − reserved − buffer ≥ 2) is serialised by the row lock: the first reserves 2 and is HELD for 5 minutes, the second rolls back and is told only 1 is left. Paid, the hold becomes COMMITTED and the picker's scan drops on_hand and reserved together; unpaid, the sweeper moves it HELD → RELEASED, and only that move gives the stock back.", opts: { start: ["race", "paid", "expired"] } },
  "sq-card-auth-standin": { title: "Card authorization and stand-in processing", summary: "A $100 purchase goes POS → acquirer → network, where a BIN lookup finds the issuer and the fraud engine adds a risk score in about 1 ms; the issuer approves and the auth code is back at the POS by about 1,800 ms, while money moves only at settlement (T+1 to T+2). If the issuer doesn't answer, the network tries its primary endpoint (500 ms) and backup (300 ms), then stand-in decides in 200 ms on the issuer's rules ($500 single limit, $2,000 daily, risk ≤ 80, not lost or stolen) and queues the decision for reconciliation.", opts: { start: ["ok", "standin"] } },
  "sq-figma-property-lww": { title: "Server-ordered, per-property last writer wins", summary: "Priya sets a button's x to 112, Arjun its fill to coral and Meera its x to 140. Each edit shows locally at once; the file's server orders them by arrival, fill and x never conflict, and the last x to arrive (140) wins on every screen. While Priya drags (100, 105, 112), Meera's earlier 140 is echoed to her: applying it would flicker, so a property with an unacknowledged local change ignores incoming values, and 112 wins anyway.", opts: { start: ["lww", "flicker"] } },
  "sq-irctc-tatkal-gate": { title: "Tatkal at 10:00: a counter in front of the database", summary: "About 280,000 requests a second running UPDATE … WHERE available_seats > 0 queue on one row lock until latency explodes. Instead an atomic Lua script on a pool counter set to 500 hands out 500 TICKET_TO_TRY results, rejects the other 1,999,500 in milliseconds with no durable storage, and only the admitted reach a single-writer allocator. A retry with the same attempt id is found in the admitted set and never burns a second seat.", opts: { start: ["row", "gate", "retry"] } },
  "sq-kite-tick-coalescing": { title: "Market data fan-out: coalesce, then skip slow sockets", summary: "Ten ticks of instrument 408065 in one second overwrite one latest-packet slot; once a second the flush encodes each changed 44-byte packet once and sends the same bytes to every subscriber, about 20 packets and 922 bytes per phone. A phone that stops reading passes 64 KB unsent, so flushes skip it and remember what it missed; after about 10 s behind it is closed (4008, slow consumer), and it reconnects, resubscribes and gets the latest values.", opts: { start: ["coalesce", "slow"] } },
  "sq-llm-continuous-batching": { title: "LLM batching: static, continuous, paged KV", summary: "In a static batch of 8, seven 50-token replies finish at step 50 and their slots idle until the 2,000-token reply ends: 1 of 8 runs for 97.5% of the batch, and new requests wait. Continuous batching schedules per step, so finished sequences leave and waiting ones join at the next step. Paged KV memory replaces a 4,096-token reservation (~1.3 GB a request) with 16-token blocks on demand, and prefix caching shares full blocks of the same instructions.", opts: { start: ["static", "cont", "paged"] } },
  "sq-netflix-abr-ladder": { title: "Adaptive bitrate: dropping and climbing the ladder", summary: "The player picks the highest rung whose bitrate × 1.2 fits the measured bandwidth and switches at 4-second chunk boundaries: 4K (15 Mbps) on 20 Mbps Wi-Fi, 720p on 5 Mbps LTE, 240p on 500 Kbps in the subway, and back up to 1080p HDR at 10 Mbps only once the buffer passes 15 s. A fixed 8 Mbps stream needs 6.4 s per 4 s chunk on LTE, so the buffer drains and playback stalls.", opts: { start: ["abr", "fixed"] } },
  "sq-s3-erasure-coding": { title: "Erasure coding: 10 + 6 shards across three AZs", summary: "A 1 MB object is Reed-Solomon encoded into 10 data and 6 parity shards of about 100 KB, placed at most 6 per Availability Zone (6, 5, 5): 1.6× storage instead of 3×, and bracketing checks that the shards decode to the original checksum before the 200 OK. When AZ-1 loses power its 6 shards are unreachable, but any 10 of 16 rebuild the object, and the repair service rebuilds the lost shards on healthy drives.", opts: { start: ["put", "az"] } },
  "sq-search-shard-fanout": { title: "Scatter-gather: the slowest shard sets the pace", summary: "A query fans out to every document shard in parallel and each returns its local top-k. Waiting for all lets one slow shard set the latency: with 1,000 shards only about 0.004% of queries avoid a slow one. With a deadline and a hedged request to the slow shard's replica, the first answer wins and the root merges about 10,000 candidates inside the 100 ms retrieval budget.", opts: { start: ["wait", "hedge"] } },
  "sq-spotify-play-path": { title: "Playing a song: signed URL, edge cache, origin, prefetch", summary: "The Stream Service checks tier, region and licensing once and returns a URL signed for 1 hour; the CDN edge verifies the token itself and serves popular tracks from cache (99%+ hit rate) in under 200 ms. A long-tail track missing at the edge is fetched from the GCS origin, so its first play is slower, and a prefetched next track plays straight from the client cache with no network wait.", opts: { start: ["edge", "origin", "prefetch"] } },
  "sq-twitter-timeline-merge": { title: "Hybrid timelines: push on write, merge on read", summary: "A tweet is stored first. An author with 1,000 followers is pushed: one batch of 1,000 ids, LPUSH into each timeline and LTRIM to 800. An author over 10,000 followers gets one ZADD to their celebrity tweets set instead. Reading, LRANGE returns the pushed ids (501, 499, 495), ZREVRANGE pulls followed celebrities' recent ids (503, 500, 498), the lists are merged newest first and one MGET hydrates them.", opts: { start: ["write", "read"] } },
  "sq-uber-h3-matching": { title: "H3 cells, ring search and dispatch", summary: "Every 4-second ping maps a driver to one resolution-9 H3 cell and moves it between cell sets only when it crosses a cell edge; its driver hash expires 30 s after pings stop. A request reads the rider's cell, then rings k = 1 and k = 2, skips busy drivers and sorts the rest by real distance. Candidates are scored (0.4 ETA, 0.2 rating, 0.2 acceptance, 0.2 wait), the best is offered the ride for 15 s, then the next.", opts: { start: ["index", "ring", "dispatch"] } },
  "sq-upi-push-flow": { title: "UPI push payment: debit, credit, deemed success", summary: "Alice pays ₹500 to bob@okaxis: NPCI resolves the VPA at Axis, debits Alice at HDFC (ref ABC123), credits Bob at Axis (ref XYZ789) and confirms in under 2 seconds, routing only messages while the money moves bank to bank. If the credit call times out, NPCI marks the payment DEEMED_SUCCESS and puts it in the settlement file; when reconciliation finds no credit, the debit is auto-reversed by T+1 with the same transaction ID.", opts: { start: ["ok", "timeout"] } },
  "sq-whatsapp-store-forward": { title: "Store and forward: ticks, offline queue, delete on ACK", summary: "The server only routes Alice's encrypted blob: one tick when it ACKs, two when Bob's device ACKs delivery, blue ticks on the read receipt. If Bob is offline the message waits in his offline queue (kept up to 30 days), is drained when he reconnects, resent if the link drops before his ACK, de-duplicated by message ID on his device, and deleted only after that ACK.", opts: { start: ["online", "offline"] } },
  "stream-lambda-kappa": { title: "Lambda vs Kappa architecture", summary: "Lambda answers today's revenue at 14:30 as the 12:00 batch view ($50,000) plus the speed layer ($12,000) = $62,000, and discards the speed results once the 18:00 batch run covers them, at the cost of two codebases. Kappa keeps one stream codebase and reprocesses by replaying the log: 1B events at 100K/s take about 3 hours before switching to the new output.", opts: { start: ["lambda", "kappa"] } },
  "sync-async-communication": { title: "Synchronous vs asynchronous communication", summary: "Synchronous: the client sends a request and is blocked until the server responds, and fails if the server is down. Asynchronous: the producer sends a message to a queue, gets an ACK at once and keeps working; the consumer processes the message later and ACKs it.", opts: { start: ["sync", "async"] } },
  "tenant-context-rls": { title: "Tenant context and row-level security", summary: "The verified JWT's tenant_id is stored in a ContextVar, the repository adds the tenant filter and the connection sets app.current_tenant, so only acme's rows come back. RLS still filters a raw query that forgot the filter, and a pooled connection must reset app.current_tenant before release or the next request inherits that tenant.", opts: { start: ["flow", "rls", "pool"] } },
  "tenant-fair-queue": { title: "Fair scheduling across tenants", summary: "Tenant A queues 100 jobs, then Tenant B queues 1. A shared FIFO makes B wait for all 100. Per-tenant queues with round-robin dequeue serve B after about one A job and cap each tenant at 100 queued. Weighted fair queuing scores (running + 1) / weight, so an enterprise task (10/20 = 0.5) runs before a free one (1/1 = 1.0).", opts: { start: ["fifo", "rr", "weighted"] } },
  "thundering-herd": { title: "Thundering herd and request coalescing", summary: "A hot key expires and every concurrent request misses at once, so the database gets one query per request and overloads. With request coalescing (single flight) the first miss fetches, the rest join that in-flight call and share its result: one database query.", opts: {} },
  "timeout-budget": { title: "Timeout budget: three calls, one 5 s SLA", summary: "The payment service calls fraud check, bank and notification in sequence under a 5 s user SLA. A 5 s timeout on each lets one payment take 15 s. A 4,500 ms budget (500 ms left for its own work) splits into 600, 3,500 and 300 ms, each capped by what is left, so even the worst case ends by about 4,400 ms.", opts: { start: ["fixed", "budget"] } },
  "token-bucket": { title: "Token bucket vs leaky bucket", summary: "Token bucket (10 tokens/s, capacity 50): a full bucket lets a burst of 30 through at once, refills 10 per second and rejects what it can't cover. Leaky bucket (10/s, queue 50): the same burst of 30 waits in the queue and leaves at a steady 10 per second.", opts: { start: ["token", "leaky"] } },
  "vector-clock-conflict": { title: "Last-write-wins vs vector clocks", summary: "Two replicas of cart [A, B] add C and D concurrently; last-write-wins keeps Node 2's [A, B, D] and silently loses C. Vector clocks detect the conflict: A writes {A:1, B:0, C:0}, B receives it and becomes {A:1, B:1, C:0}, C writes {A:0, B:0, C:1}; neither of A's and C's clocks is before the other, so the writes are concurrent.", opts: { start: ["lww", "vector"] } },
  "webhook-retry-recovery": { title: "Webhook retries after a 2-hour outage", summary: "A partner endpoint is down from 2:00 to 4:00 PM. With plain exponential backoff each event waits on its own timer (Event 1's next retry is 5:21 PM), so deliveries trickle in until about 6:00 PM. A health check that moves all 10,000 pending retries to the immediate queue at 4:00 delivers them by 4:13 PM at the endpoint's ~13/s rate limit.", opts: { start: ["default", "fast"] } },
};

export const ANIM_NAMES = Object.keys(ANIMS);

/** Attributes every explainer accepts, on top of its own `opts`. */
export const COMMON_ANIM_OPTS: Readonly<Record<string, AnimOpt>> = { title: "text", start: "text", autoplay: ["on", "off"] };
